add("de","A2","Deyimler","Gib mir einen Moment zum Nachdenken","düşünmem için bana bir dakika ver","Ausdruck","Gib mir bitte einen Moment zum Nachdenken.","Lütfen düşünmem için bana bir dakika ver.");
add("de","A2","Deyimler","Ich muss noch mal überlegen","tekrar düşünmem gerekiyor","Ausdruck","Warte, ich muss noch mal überlegen.","Bekle, tekrar düşünmem gerekiyor.");
add("de","A2","Deyimler","Ich habe es mir anders überlegt","fikrimi değiştirdim","Ausdruck","Ehrlich, ich habe es mir anders überlegt.","Dürüst olmak gerekirse, fikrimi değiştirdim.");
add("de","A2","Deyimler","Ich habe meine Meinung geändert","fikrimi değiştirdim","Ausdruck","Nach dem Gespräch habe ich meine Meinung geändert.","Konuşmadan sonra fikrimi değiştirdim.");
add("de","A2","Deyimler","Ich bleibe bei meiner Meinung","fikrimde kalıyorum","Ausdruck","Nein, ich bleibe bei meiner Meinung.","Hayır, fikrimde kalıyorum.");
add("de","A2","Deyimler","Am Ende des Tages","günün sonunda","Ausdruck","Am Ende des Tages ist Familie das Wichtigste.","Günün sonunda aile en önemlisidir.");
add("de","A2","Deyimler","Zu guter Letzt","son olarak","Ausdruck","Zu guter Letzt möchte ich mich bedanken.","Son olarak teşekkür etmek istiyorum.");
add("de","A2","Deyimler","Am Anfang war es schwer","başlangıçta zordu","Ausdruck","Am Anfang war es wirklich schwer für mich.","Başlangıçta benim için gerçekten zordu.");
add("de","A2","Deyimler","Mit der Zeit wird es leichter","zamanla kolaylaşır","Ausdruck","Keine Sorge, mit der Zeit wird es leichter.","Merak etme, zamanla kolaylaşır.");
add("de","A2","Deyimler","Schritt für Schritt","adım adım","Ausdruck","Wir machen das Schritt für Schritt.","Bunu adım adım yapıyoruz.");
add("de","A2","Deyimler","Von Anfang an","en baştan","Ausdruck","Erklär mir das von Anfang an.","Bunu bana en baştan anlat.");
add("de","A2","Deyimler","Bis zum Ende","sona kadar","Ausdruck","Ich bleibe bis zum Ende.","Sona kadar kalıyorum.");
add("de","A2","Deyimler","Von Zeit zu Zeit","zaman zaman","Ausdruck","Wir treffen uns von Zeit zu Zeit.","Zaman zaman buluşuyoruz.");
add("de","A2","Deyimler","Ab und zu","ara sıra","Ausdruck","Ab und zu gehe ich ins Kino.","Ara sıra sinemaya giderim.");
add("de","A2","Deyimler","Immer wieder","tekrar tekrar","Ausdruck","Er macht immer wieder den gleichen Fehler.","Tekrar tekrar aynı hatayı yapıyor.");
add("de","A2","Deyimler","Ein für alle Mal","bir kez ve son olarak","Ausdruck","Lass uns das ein für alle Mal klären.","Hadi bunu bir kez ve son olarak netleştirelim.");
add("de","A2","Deyimler","Auf lange Zeit","uzun süre","Ausdruck","Wir sind auf lange Zeit verreist.","Uzun süre için seyahate çıktık.");
add("de","A2","Deyimler","Für den Moment","şimdilik","Ausdruck","Für den Moment ist alles gut.","Şimdilik her şey yolunda.");
add("de","A2","Deyimler","Nur für kurze Zeit","sadece kısa bir süre için","Ausdruck","Ich bin nur für kurze Zeit hier.","Burada sadece kısa bir süre için bulunuyorum.");
add("de","A2","Deyimler","Es dauert nicht lange","uzun sürmez","Ausdruck","Keine Sorge, es dauert nicht lange.","Merak etme, uzun sürmez.");
add("de","A2","Deyimler","Das dauert ewig","bu sonsuza kadar sürer","Ausdruck","Ehrlich, das dauert ja ewig!","Dürüst olmak gerekirse, bu sonsuza kadar sürüyor!");
add("de","A2","Deyimler","Wir haben keine Zeit zu verlieren","kaybedecek zamanımız yok","Ausdruck","Beeilen wir uns, wir haben keine Zeit zu verlieren.","Acele edelim, kaybedecek zamanımız yok.");
add("de","A2","Deyimler","Zeit ist Geld","zaman nakittir","Ausdruck","Beeil dich, Zeit ist Geld.","Acele et, zaman nakittir.");
add("de","A2","Deyimler","Die Zeit vergeht schnell","zaman hızlı geçiyor","Ausdruck","Wow, die Zeit vergeht wirklich schnell.","Vay, zaman gerçekten hızlı geçiyor.");
add("de","A2","Deyimler","Wie die Zeit vergeht","zaman nasıl da geçiyor","Ausdruck","Unglaublich, wie die Zeit vergeht.","İnanılmaz, zaman nasıl da geçiyor.");
add("de","A2","Deyimler","Die Zeit ist um","süre doldu","Ausdruck","Tut mir leid, die Zeit ist um.","Üzgünüm, süre doldu.");
add("de","A2","Deyimler","Es ist noch früh","henüz erken","Ausdruck","Bleib noch, es ist noch früh.","Kal biraz daha, henüz erken.");
add("de","A2","Deyimler","Es ist schon spät","çok geç oldu","Ausdruck","Ich muss gehen, es ist schon spät.","Gitmeliyim, çok geç oldu.");
add("de","A2","Deyimler","Wir sind gerade rechtzeitig","tam vaktinde geldik","Ausdruck","Gut, wir sind gerade rechtzeitig angekommen.","İyi, tam vaktinde geldik.");
add("de","A2","Deyimler","Wir haben es knapp geschafft","zar zor yetiştirdik","Ausdruck","Puh, wir haben es gerade so knapp geschafft.","Öf, zar zor yetiştirdik.");
add("de","A2","Deyimler","Wir sind zu spät dran","geç kaldık","Ausdruck","Beeil dich, wir sind zu spät dran.","Acele et, geç kaldık.");
add("de","A2","Deyimler","Wir haben noch genug Zeit","hâlâ yeterince zamanımız var","Ausdruck","Keine Panik, wir haben noch genug Zeit.","Panik yok, hâlâ yeterince zamanımız var.");
add("de","A2","Deyimler","Beeil dich nicht so","bu kadar acele etme","Ausdruck","Beeil dich nicht so, wir haben Zeit.","Bu kadar acele etme, vaktimiz var.");
add("de","A2","Deyimler","Wir haben alle Zeit der Welt","bütün zamanımız var","Ausdruck","Entspann dich, wir haben alle Zeit der Welt.","Rahatla, bütün zamanımız var.");
add("de","A2","Deyimler","Kannst du mir einen Gefallen tun?","bana bir iyilik yapabilir misin?","Ausdruck","Kannst du mir bitte einen Gefallen tun?","Lütfen bana bir iyilik yapabilir misin?");
add("de","A2","Deyimler","Ich brauche deine Hilfe","yardımına ihtiyacım var","Ausdruck","Ehrlich, ich brauche jetzt deine Hilfe.","Dürüst olmak gerekirse, şimdi yardımına ihtiyacım var.");
add("de","A2","Deyimler","Kannst du mir dabei helfen?","bunu yapmama yardım edebilir misin?","Ausdruck","Kannst du mir bitte dabei helfen?","Lütfen bunu yapmama yardım edebilir misin?");
add("de","A2","Deyimler","Lass mich dir helfen","yardım edeyim","Ausdruck","Warte, lass mich dir helfen.","Bekle, yardım edeyim.");
add("de","A2","Deyimler","Ich helfe dir gerne","sana seve seve yardım ederim","Ausdruck","Kein Problem, ich helfe dir gerne.","Sorun değil, sana seve seve yardım ederim.");
add("de","A2","Deyimler","Brauchst du sonst noch etwas?","başka bir şeye ihtiyacın var mı?","Ausdruck","Brauchst du sonst noch etwas von mir?","Benden başka bir şeye ihtiyacın var mı?");
add("de","A2","Deyimler","Ich komme klar","idare ederim","Ausdruck","Danke, aber ich komme schon klar.","Teşekkürler ama idare ederim.");
add("de","A2","Deyimler","Ich schaffe es allein","tek başıma yapabilirim","Ausdruck","Danke, ich schaffe es allein.","Teşekkürler, tek başıma yapabilirim.");
add("de","A2","Deyimler","Kann ich dich um etwas bitten?","senden bir şey rica edebilir miyim?","Ausdruck","Kann ich dich kurz um etwas bitten?","Senden kısaca bir şey rica edebilir miyim?");
add("de","A2","Deyimler","Würdest du mir bitte helfen?","lütfen bana yardım eder misin?","Ausdruck","Würdest du mir bitte kurz helfen?","Lütfen bana kısaca yardım eder misin?");
add("de","A2","Deyimler","Stört es dich, wenn ich...","...sana bir sakıncası var mı?","Ausdruck","Stört es dich, wenn ich das Fenster öffne?","Pencereyi açmamın sana bir sakıncası var mı?");
add("de","A2","Deyimler","Macht es dir etwas aus?","senin için sorun olur mu?","Ausdruck","Macht es dir etwas aus, kurz zu warten?","Kısaca beklemek senin için sorun olur mu?");
add("de","A2","Deyimler","Hättest du etwas dagegen?","buna itirazın olur muydu?","Ausdruck","Hättest du etwas dagegen, wenn ich mitkomme?","Ben de gelirsem buna itirazın olur muydu?");
add("de","A2","Deyimler","Ich hätte eine Bitte","bir ricam olacaktı","Ausdruck","Entschuldigung, ich hätte eine kleine Bitte.","Affedersiniz, küçük bir ricam olacaktı.");
add("de","A2","Deyimler","Wäre es möglich...","...mümkün olur muydu?","Ausdruck","Wäre es möglich, das morgen zu machen?","Bunu yarın yapmak mümkün olur muydu?");
add("de","A2","Deyimler","Gibt es eine Möglichkeit...","...bir yolu var mı?","Ausdruck","Gibt es eine Möglichkeit, das zu ändern?","Bunu değiştirmenin bir yolu var mı?");
add("de","A2","Deyimler","Ich weiß nicht, wie ich das machen soll","bunu nasıl yapacağımı bilmiyorum","Ausdruck","Ehrlich, ich weiß nicht, wie ich das machen soll.","Dürüst olmak gerekirse, bunu nasıl yapacağımı bilmiyorum.");
add("de","A2","Deyimler","Zeig mir, wie das geht","bana nasıl yapıldığını göster","Ausdruck","Kannst du mir zeigen, wie das geht?","Bana bunun nasıl yapıldığını gösterebilir misin?");
add("de","A2","Deyimler","Ich zeige es dir","sana gösteririm","Ausdruck","Warte, ich zeige es dir.","Bekle, sana gösteririm.");
add("de","A2","Deyimler","Pass gut auf","dikkatli izle / iyi bak","Ausdruck","Pass gut auf, ich mache es nur einmal.","İyi bak, sadece bir kere yapacağım.");
add("de","A2","Deyimler","Folge mir","beni takip et","Ausdruck","Folge mir einfach, ich zeige dir den Weg.","Sadece beni takip et, sana yolu gösteririm.");
add("de","A2","Deyimler","Mach es genau wie ich","tam benim gibi yap","Ausdruck","Mach es einfach genau wie ich.","Sadece tam benim gibi yap.");
add("de","A2","Deyimler","Versuch es noch einmal","tekrar dene","Ausdruck","Gib nicht auf, versuch es noch einmal.","Pes etme, tekrar dene.");
add("de","A2","Deyimler","Übe es weiter","pratik yapmaya devam et","Ausdruck","Übe es einfach weiter, du wirst besser.","Sadece pratik yapmaya devam et, daha iyi olacaksın.");
add("de","A2","Deyimler","Du machst Fortschritte","gelişme kaydediyorsun","Ausdruck","Ehrlich, du machst wirklich Fortschritte.","Dürüst olmak gerekirse, gerçekten gelişme kaydediyorsun.");
add("de","A2","Deyimler","Du wirst immer besser","gittikçe daha iyi oluyorsun","Ausdruck","Du wirst wirklich von Tag zu Tag besser.","Gerçekten gün geçtikçe daha iyi oluyorsun.");
add("de","A2","Deyimler","Weiter so","böyle devam et","Ausdruck","Super, weiter so!","Harika, böyle devam et!");
add("de","A2","Deyimler","Das war knapp","bu ucu ucuna oldu","Ausdruck","Puh, das war wirklich knapp.","Öf, bu gerçekten ucu ucuna oldu.");
add("de","A2","Deyimler","Gerade noch geschafft","zar zor başardım","Ausdruck","Puh, gerade noch geschafft!","Öf, zar zor başardım!");
add("de","A2","Deyimler","Fast hätte ich es vergessen","neredeyse unutuyordum","Ausdruck","Oh, fast hätte ich es vergessen!","Ah, neredeyse unutuyordum!");
add("de","A2","Deyimler","Zum Glück habe ich daran gedacht","iyi ki hatırladım","Ausdruck","Zum Glück habe ich rechtzeitig daran gedacht.","İyi ki zamanında hatırladım.");
add("de","A2","Deyimler","Ich hätte fast etwas Wichtiges vergessen","önemli bir şeyi neredeyse unutuyordum","Ausdruck","Warte, ich hätte fast etwas Wichtiges vergessen.","Bekle, önemli bir şeyi neredeyse unutuyordum.");
add("de","A2","Deyimler","Das fällt mir gerade ein","az önce aklıma geldi","Ausdruck","Ach, das fällt mir gerade ein.","Ah, az önce aklıma geldi.");
add("de","A2","Deyimler","Mir fällt der Name nicht ein","adı aklıma gelmiyor","Ausdruck","Ehrlich, mir fällt gerade der Name nicht ein.","Dürüst olmak gerekirse, adı şu an aklıma gelmiyor.");
add("de","A2","Deyimler","Es liegt mir auf der Zunge","dilimin ucunda","Ausdruck","Warte, es liegt mir auf der Zunge.","Bekle, dilimin ucunda.");
add("de","A2","Deyimler","Jetzt fällt es mir wieder ein","şimdi tekrar aklıma geldi","Ausdruck","Ah, jetzt fällt es mir wieder ein!","Ah, şimdi tekrar aklıma geldi!");
add("de","A2","Deyimler","Ich habe es total vergessen","tamamen unuttum","Ausdruck","Ehrlich, ich habe es total vergessen.","Dürüst olmak gerekirse, tamamen unuttum.");
add("de","A2","Deyimler","Merk dir das gut","bunu iyi hatırla","Ausdruck","Merk dir das gut für nächstes Mal.","Bunu gelecek sefer için iyi hatırla.");
add("de","A2","Deyimler","Präg dir das ein","bunu aklına kaz","Ausdruck","Präg dir das gut ein.","Bunu iyi aklına kaz.");
add("de","A2","Deyimler","Wie findest du das?","bunu nasıl buluyorsun?","Ausdruck","Sag mal, wie findest du das neue Restaurant?","Söyle bakalım, yeni restoranı nasıl buluyorsun?");
add("de","A2","Deyimler","Ich finde das toll","bunu harika buluyorum","Ausdruck","Ehrlich, ich finde das echt toll.","Dürüst olmak gerekirse, bunu gerçekten harika buluyorum.");
add("de","A2","Deyimler","Ich finde das nicht so gut","bunu pek iyi bulmuyorum","Ausdruck","Ehrlich gesagt, ich finde das nicht so gut.","Dürüst söylemek gerekirse, bunu pek iyi bulmuyorum.");
add("de","A2","Deyimler","Das gefällt mir sehr","bunu çok beğeniyorum","Ausdruck","Wow, das gefällt mir wirklich sehr.","Vay, bunu gerçekten çok beğeniyorum.");
add("de","A2","Deyimler","Das gefällt mir nicht","bunu beğenmiyorum","Ausdruck","Ehrlich, das gefällt mir gar nicht.","Dürüst olmak gerekirse, bunu hiç beğenmiyorum.");
add("de","A2","Deyimler","Was gefällt dir daran?","bunda neyi beğeniyorsun?","Ausdruck","Sag mal, was gefällt dir daran am meisten?","Söyle bakalım, bunda en çok neyi beğeniyorsun?");
add("de","A2","Deyimler","Am liebsten mag ich","en çok şunu severim","Ausdruck","Am liebsten mag ich die Farbe Blau.","En çok mavi rengi severim.");
add("de","A2","Deyimler","Ich mag es nicht besonders","pek sevmiyorum","Ausdruck","Ehrlich, ich mag das nicht besonders.","Dürüst olmak gerekirse, bunu pek sevmiyorum.");
add("de","A2","Deyimler","Ich habe eine Schwäche dafür","buna zaafım var","Ausdruck","Ehrlich, ich habe eine Schwäche für Schokolade.","Dürüst olmak gerekirse, çikolataya zaafım var.");
add("de","A2","Deyimler","Ich bin ein großer Fan davon","bunun büyük hayranıyım","Ausdruck","Ehrlich, ich bin ein großer Fan davon.","Dürüst olmak gerekirse, bunun büyük hayranıyım.");
add("de","A2","Deyimler","Das ist nicht mein Ding","bu benim tarzım değil","Ausdruck","Ehrlich, Fußball ist nicht mein Ding.","Dürüst olmak gerekirse, futbol benim tarzım değil.");
add("de","A2","Deyimler","Das ist genau mein Ding","bu tam benim tarzım","Ausdruck","Wow, das ist genau mein Ding!","Vay, bu tam benim tarzım!");
add("de","A2","Deyimler","Ich bin darauf nicht so scharf","buna pek meraklı değilim","Ausdruck","Ehrlich, ich bin darauf nicht so scharf.","Dürüst olmak gerekirse, buna pek meraklı değilim.");
add("de","A2","Deyimler","Ich bin ganz verrückt danach","buna bayılıyorum","Ausdruck","Ehrlich, ich bin ganz verrückt nach Kaffee.","Dürüst olmak gerekirse, kahveye bayılıyorum.");
add("de","A2","Deyimler","Das ist genau mein Geschmack","tam benim zevkime uygun","Ausdruck","Ehrlich, das ist genau mein Geschmack.","Dürüst olmak gerekirse, bu tam benim zevkime uygun.");
add("de","A2","Deyimler","Das entspricht nicht meinem Geschmack","zevkime uygun değil","Ausdruck","Ehrlich, das entspricht nicht ganz meinem Geschmack.","Dürüst olmak gerekirse, bu tam zevkime uygun değil.");
add("de","A2","Deyimler","Ich ziehe das vor","bunu tercih ederim","Ausdruck","Ehrlich, ich ziehe Tee dem Kaffee vor.","Dürüst olmak gerekirse, çayı kahveye tercih ederim.");
add("de","A2","Deyimler","Ich habe lieber","daha çok isterim","Ausdruck","Ich habe lieber Ruhe als Party.","Partiden çok huzuru isterim.");
add("de","A2","Deyimler","Mir wäre lieber, wenn","tercih ederdim ki","Ausdruck","Mir wäre lieber, wenn wir früh gehen.","Erken gitmemizi tercih ederdim.");
add("de","A2","Deyimler","Egal was du wählst","ne seçersen seç","Ausdruck","Egal was du wählst, ich bin einverstanden.","Ne seçersen seç, kabul ediyorum.");
add("de","A2","Deyimler","Es ist mir egal welche","hangisi olduğu umurumda değil","Ausdruck","Es ist mir egal, welche Farbe.","Hangi renk olduğu umurumda değil.");
add("de","A2","Deyimler","Du hast die Wahl","seçim senin","Ausdruck","Du hast die Wahl, ich bin flexibel.","Seçim senin, ben esneğim.");
add("de","A2","Deyimler","Wähl du aus","sen seç","Ausdruck","Wähl du aus, mir ist alles recht.","Sen seç, benim için hepsi uygun.");
add("de","A2","Deyimler","Wie du entscheidest, ist okay","nasıl karar verirsen ver, tamam","Ausdruck","Wie du entscheidest, ist für mich okay.","Nasıl karar verirsen ver, benim için tamam.");
add("de","A2","Deyimler","Ich lasse dich entscheiden","kararı sana bırakıyorum","Ausdruck","Ich lasse dich diesmal entscheiden.","Bu sefer kararı sana bırakıyorum.");
add("de","A2","Deyimler","Ich kann mich nicht entscheiden","karar veremiyorum","Ausdruck","Ehrlich, ich kann mich einfach nicht entscheiden.","Dürüst olmak gerekirse, bir türlü karar veremiyorum.");
add("de","A2","Deyimler","Das fällt mir schwer","bu benim için zor","Ausdruck","Ehrlich, diese Entscheidung fällt mir schwer.","Dürüst olmak gerekirse, bu karar benim için zor.");
add("de","A2","Deyimler","Das fällt mir leicht","bu benim için kolay","Ausdruck","Ehrlich, das fällt mir ziemlich leicht.","Dürüst olmak gerekirse, bu benim için oldukça kolay.");
add("de","A2","Deyimler","Ich bin gut darin","bunda iyiyim","Ausdruck","Ehrlich, ich bin ziemlich gut darin.","Dürüst olmak gerekirse, bunda oldukça iyiyim.");
add("de","A2","Deyimler","Ich bin nicht so gut darin","bunda pek iyi değilim","Ausdruck","Ehrlich, ich bin nicht so gut darin.","Dürüst olmak gerekirse, bunda pek iyi değilim.");
add("de","A2","Deyimler","Das liegt mir nicht","bu bana göre değil","Ausdruck","Ehrlich, Kochen liegt mir nicht.","Dürüst olmak gerekirse, yemek yapmak bana göre değil.");
add("de","A2","Deyimler","Das liegt mir sehr","bu tam bana göre","Ausdruck","Ehrlich, Sprachen lernen liegt mir sehr.","Dürüst olmak gerekirse, dil öğrenmek tam bana göre.");
add("de","A2","Deyimler","Ich bin ein Naturtalent darin","bunda doğal yetenekliyim","Ausdruck","Ehrlich, sie ist ein Naturtalent darin.","Dürüst olmak gerekirse, o bunda doğal yetenekli.");
add("de","A2","Deyimler","Ich muss es noch üben","hâlâ pratik yapmam gerekiyor","Ausdruck","Ehrlich, ich muss es noch viel üben.","Dürüst olmak gerekirse, hâlâ çok pratik yapmam gerekiyor.");
add("de","A2","Deyimler","Es kommt mit der Zeit","zamanla gelir","Ausdruck","Keine Sorge, es kommt mit der Zeit.","Merak etme, zamanla gelir.");
add("de","A2","Deyimler","Ich habe vor, das zu tun","bunu yapmayı planlıyorum","Ausdruck","Ich habe vor, nächstes Jahr zu reisen.","Gelecek yıl seyahat etmeyi planlıyorum.");
add("de","A2","Deyimler","Was hast du vor?","ne planlıyorsun?","Ausdruck","Was hast du für dieses Wochenende vor?","Bu hafta sonu için ne planlıyorsun?");
add("de","A2","Deyimler","Ich habe noch keine Pläne","henüz bir planım yok","Ausdruck","Ehrlich, ich habe noch keine Pläne für morgen.","Dürüst olmak gerekirse, yarın için henüz bir planım yok.");
add("de","A2","Deyimler","Hast du schon Pläne?","planların var mı zaten?","Ausdruck","Hast du schon Pläne für heute Abend?","Bu akşam için zaten planların var mı?");
add("de","A2","Deyimler","Wollen wir zusammen etwas machen?","birlikte bir şey yapalım mı?","Ausdruck","Wollen wir am Samstag zusammen etwas machen?","Cumartesi birlikte bir şey yapalım mı?");
add("de","A2","Deyimler","Hast du Lust mitzukommen?","gelmek ister misin?","Ausdruck","Hast du Lust, mit uns mitzukommen?","Bizimle gelmek ister misin?");
add("de","A2","Deyimler","Ich habe Lust dazu","canım öyle istiyor","Ausdruck","Ehrlich, ich habe heute Lust auf Pizza.","Dürüst olmak gerekirse, bugün canım pizza istiyor.");
add("de","A2","Deyimler","Ich habe keine Lust","canım istemiyor","Ausdruck","Ehrlich, ich habe heute keine Lust auszugehen.","Dürüst olmak gerekirse, bugün dışarı çıkmak canım istemiyor.");
add("de","A2","Deyimler","Worauf hast du Lust?","canın ne istiyor?","Ausdruck","Sag mal, worauf hast du gerade Lust?","Söyle bakalım, şu an canın ne istiyor?");
add("de","A2","Deyimler","Ich habe Lust auf etwas Süßes","canım tatlı bir şey istiyor","Ausdruck","Ehrlich, ich habe Lust auf etwas Süßes.","Dürüst olmak gerekirse, canım tatlı bir şey istiyor.");
add("de","A2","Deyimler","Ich könnte etwas essen","bir şeyler yiyebilirdim","Ausdruck","Ehrlich, ich könnte jetzt etwas essen.","Dürüst olmak gerekirse, şimdi bir şeyler yiyebilirdim.");
add("de","A2","Deyimler","Sollen wir etwas bestellen?","bir şeyler sipariş verelim mi?","Ausdruck","Sollen wir uns etwas zu essen bestellen?","Yiyecek bir şeyler sipariş verelim mi?");
add("de","A2","Deyimler","Was möchtest du machen?","ne yapmak istersin?","Ausdruck","Sag mal, was möchtest du heute Abend machen?","Söyle bakalım, bu akşam ne yapmak istersin?");
add("de","A2","Deyimler","Mir ist alles recht","benim için hepsi uygun","Ausdruck","Egal was, mir ist alles recht.","Ne olursa olsun, benim için hepsi uygun.");
add("de","A2","Deyimler","Wie klingt das für dich?","sana nasıl geliyor?","Ausdruck","Wie klingt das für dich, gehen wir ins Kino?","Sinemaya gitmek sana nasıl geliyor?");
add("de","A2","Deyimler","Das klingt nach einem guten Plan","bu iyi bir plan gibi","Ausdruck","Das klingt wirklich nach einem guten Plan.","Bu gerçekten iyi bir plan gibi geliyor.");
add("de","A2","Deyimler","Machen wir das so","bunu böyle yapalım","Ausdruck","Okay, machen wir das dann so.","Tamam, o zaman bunu böyle yapalım.");
add("de","A2","Deyimler","Abgemacht","anlaştık (kısa)","Ausdruck","Gut, abgemacht dann!","İyi, o zaman anlaştık!");
add("de","A2","Deyimler","Gesagt, getan","laf üzerine iş (hemen yapmak)","Ausdruck","Gesagt, getan, wir gehen jetzt.","Söylenen yapılır, şimdi gidiyoruz.");
add("de","A2","Deyimler","Ich bin sofort dabei","hemen katılırım","Ausdruck","Klar, ich bin sofort dabei!","Tabii, hemen katılırım!");
add("de","A2","Deyimler","Zähl auf mich","bana güvenebilirsin","Ausdruck","Klar, du kannst auf mich zählen.","Tabii, bana güvenebilirsin.");
add("de","A2","Deyimler","Verlass dich auf mich","bana güven","Ausdruck","Verlass dich einfach auf mich.","Sadece bana güven.");
add("de","A2","Deyimler","Ich werde nicht enttäuschen","hayal kırıklığına uğratmayacağım","Ausdruck","Keine Sorge, ich werde dich nicht enttäuschen.","Merak etme, seni hayal kırıklığına uğratmayacağım.");
add("de","A2","Deyimler","Ich bleibe meinem Wort treu","sözümde dururum","Ausdruck","Keine Sorge, ich bleibe meinem Wort treu.","Merak etme, sözümde dururum.");
add("de","A2","Deyimler","Mein Wort darauf","sözüm üzerine","Ausdruck","Ich mache das, mein Wort darauf.","Bunu yapacağım, sözüm üzerine.");
add("de","A2","Deyimler","Ich verspreche es dir","sana söz veriyorum","Ausdruck","Ich verspreche es dir, ehrlich.","Sana söz veriyorum, dürüstçe.");
add("de","A2","Deyimler","Auf mein Ehrenwort","şerefim üzerine","Ausdruck","Auf mein Ehrenwort, ich lüge nicht.","Şerefim üzerine, yalan söylemiyorum.");
add("de","A2","Deyimler","Ich schwöre es","yemin ederim","Ausdruck","Ich schwöre es, das ist die Wahrheit.","Yemin ederim, bu gerçek.");
add("de","A2","Deyimler","Das ist die reine Wahrheit","bu saf gerçek","Ausdruck","Ehrlich, das ist die reine Wahrheit.","Dürüst olmak gerekirse, bu saf gerçek.");
add("de","A2","Deyimler","Ich lüge nicht","yalan söylemiyorum","Ausdruck","Ehrlich, ich lüge dich nicht an.","Dürüst olmak gerekirse, sana yalan söylemiyorum.");
add("de","A2","Deyimler","Ich mache keine Witze","şaka yapmıyorum","Ausdruck","Ehrlich, ich mache jetzt keine Witze.","Dürüst olmak gerekirse, şimdi şaka yapmıyorum.");
add("de","A2","Deyimler","Ich meine es ernst","ciddiyim","Ausdruck","Ehrlich, ich meine es diesmal ernst.","Dürüst olmak gerekirse, bu sefer ciddiyim.");
add("de","A2","Deyimler","Das war nur ein Witz","bu sadece bir şakaydı","Ausdruck","Ehrlich, das war nur ein Witz.","Dürüst olmak gerekirse, bu sadece bir şakaydı.");
add("de","A2","Deyimler","Ich habe nur Spaß gemacht","sadece şaka yapıyordum","Ausdruck","Ehrlich, ich habe nur Spaß gemacht.","Dürüst olmak gerekirse, sadece şaka yapıyordum.");
add("de","A2","Deyimler","Nimm es nicht so ernst","bunu bu kadar ciddiye alma","Ausdruck","Komm schon, nimm es nicht so ernst.","Hadi ama, bunu bu kadar ciddiye alma.");
add("de","A2","Deyimler","Sei nicht traurig","üzülme","Ausdruck","Sei nicht traurig, alles wird gut.","Üzülme, her şey yoluna girecek.");
add("de","A2","Deyimler","Weine nicht","ağlama","Ausdruck","Weine nicht, ich bin hier bei dir.","Ağlama, ben senin yanındayım.");
add("de","A2","Deyimler","Es ist nicht so schlimm","o kadar da kötü değil","Ausdruck","Komm schon, es ist nicht so schlimm.","Hadi ama, o kadar da kötü değil.");
add("de","A2","Deyimler","Es könnte schlimmer sein","daha kötü olabilirdi","Ausdruck","Sieh es positiv, es könnte schlimmer sein.","Olumlu bak, daha kötü olabilirdi.");
add("de","A2","Deyimler","Es gibt Schlimmeres","daha kötüsü var","Ausdruck","Denk daran, es gibt Schlimmeres.","Unutma, daha kötüsü var.");
add("de","A2","Deyimler","Morgen sieht alles anders aus","yarın her şey farklı görünecek","Ausdruck","Schlaf jetzt, morgen sieht alles anders aus.","Şimdi uyu, yarın her şey farklı görünecek.");
add("de","A2","Deyimler","Nach dem Regen kommt Sonnenschein","yağmurdan sonra güneş açar","Ausdruck","Keine Sorge, nach dem Regen kommt Sonnenschein.","Merak etme, yağmurdan sonra güneş açar.");
add("de","A2","Deyimler","Jede Wolke hat einen Silberstreif","her bulutun bir gümüş kenarı vardır","Ausdruck","Bleib positiv, jede Wolke hat einen Silberstreif.","Pozitif kal, her bulutun bir gümüş kenarı vardır.");
add("de","A2","Deyimler","Es wird alles gut werden","her şey iyi olacak","Ausdruck","Vertrau mir, es wird alles gut werden.","Bana güven, her şey iyi olacak.");
add("de","A2","Deyimler","Denk positiv","olumlu düşün","Ausdruck","Denk positiv, es klappt schon.","Olumlu düşün, işe yarayacak.");
add("de","A2","Deyimler","Bleib stark","güçlü kal","Ausdruck","Bleib stark, du schaffst das.","Güçlü kal, başaracaksın.");
add("de","A2","Deyimler","Gib die Hoffnung nicht auf","umudunu kaybetme","Ausdruck","Gib die Hoffnung niemals auf.","Umudunu asla kaybetme.");
add("de","A2","Deyimler","Es gibt immer einen Weg","her zaman bir yol vardır","Ausdruck","Keine Sorge, es gibt immer einen Weg.","Merak etme, her zaman bir yol vardır.");
add("de","A2","Deyimler","Wo ein Wille ist, ist auch ein Weg","isteyen bir yolunu bulur","Ausdruck","Glaub mir, wo ein Wille ist, ist auch ein Weg.","İnan bana, isteyen bir yolunu bulur.");
add("de","A2","Deyimler","Träume groß","büyük hayaller kur","Ausdruck","Träume groß und arbeite hart.","Büyük hayaller kur ve sıkı çalış.");
add("de","A2","Deyimler","Glaub an dich selbst","kendine inan","Ausdruck","Glaub einfach an dich selbst.","Sadece kendine inan.");
add("de","A2","Deyimler","Du bist stärker, als du denkst","düşündüğünden daha güçlüsün","Ausdruck","Du bist wirklich stärker, als du denkst.","Gerçekten düşündüğünden daha güçlüsün.");
add("de","A2","Deyimler","Du kannst alles erreichen","her şeyi başarabilirsin","Ausdruck","Mit harter Arbeit kannst du alles erreichen.","Sıkı çalışmayla her şeyi başarabilirsin.");
add("de","A2","Deyimler","Sei stolz auf dich","kendinle gurur duy","Ausdruck","Sei stolz auf dich, du hast es geschafft.","Kendinle gurur duy, başardın.");
add("de","A2","Deyimler","Du hast das verdient","bunu hak ettin","Ausdruck","Du hast diesen Erfolg wirklich verdient.","Bu başarıyı gerçekten hak ettin.");
add("de","A2","Deyimler","Ich bin sehr stolz auf dich","seninle çok gurur duyuyorum","Ausdruck","Ehrlich, ich bin so unglaublich stolz auf dich.","Dürüst olmak gerekirse, seninle inanılmaz gurur duyuyorum.");
add("de","A2","Deyimler","Weiter geht's","hadi devam","Ausdruck","Okay, weiter geht's!","Tamam, hadi devam!");
add("de","A2","Deyimler","Auf geht's","hadi başlayalım","Ausdruck","Auf geht's, wir schaffen das.","Hadi başlayalım, bunu başaracağız.");
add("de","A2","Deyimler","Los geht's","hadi başlıyoruz","Ausdruck","Alle bereit? Los geht's!","Herkes hazır mı? Hadi başlıyoruz!");
add("de","A2","Deyimler","Auf die Plätze, fertig, los","hazır, ol, başla","Ausdruck","Auf die Plätze, fertig, los!","Hazır, ol, başla!");
add("de","A2","Deyimler","Jetzt geht's richtig los","şimdi gerçekten başlıyor","Ausdruck","Achtung, jetzt geht's richtig los!","Dikkat, şimdi gerçekten başlıyor!");
add("de","A2","Deyimler","Das war's","bu kadardı","Ausdruck","Okay, das war's für heute.","Tamam, bugünlük bu kadardı.");
add("de","A2","Deyimler","Das war's dann wohl","sanırım bu kadardı","Ausdruck","Na gut, das war's dann wohl.","Peki, sanırım bu kadardı.");
add("de","A2","Deyimler","Schluss damit","yeter bu kadar","Ausdruck","Jetzt Schluss damit, bitte.","Şimdi yeter bu kadar, lütfen.");
add("de","A2","Deyimler","Damit ist es erledigt","böylece bitti","Ausdruck","Gut, damit ist es erledigt.","İyi, böylece bitti.");
add("de","A2","Deyimler","Punkt und Ende","nokta ve son (bitti)","Ausdruck","Ich gehe nicht, Punkt und Ende.","Gitmiyorum, nokta ve son.");
add("de","A2","Deyimler","Ende der Diskussion","tartışma sona ersin","Ausdruck","Nein, Ende der Diskussion.","Hayır, tartışma sona ersin.");
add("de","A2","Deyimler","Damit hat es sich","bu kadar yeter (kesin)","Ausdruck","Nein, damit hat es sich.","Hayır, bu kadar yeter.");
add("de","A2","Deyimler","Das war's von meiner Seite","benim tarafımdan bu kadardı","Ausdruck","Okay, das war's von meiner Seite.","Tamam, benim tarafımdan bu kadardı.");
add("de","A2","Deyimler","Ich hab dich lieb","seni seviyorum (aile/arkadaş)","Ausdruck","Ich hab dich sehr lieb, Mama.","Seni çok seviyorum, anne.");
add("de","A2","Deyimler","Ich liebe dich","seni seviyorum (romantik)","Ausdruck","Ich liebe dich von ganzem Herzen.","Seni tüm kalbimle seviyorum.");
add("de","A2","Deyimler","Ich mag dich sehr","senden çok hoşlanıyorum","Ausdruck","Ehrlich, ich mag dich wirklich sehr.","Dürüst olmak gerekirse, senden gerçekten çok hoşlanıyorum.");
add("de","A2","Deyimler","Du bedeutest mir viel","sen benim için çok önemlisin","Ausdruck","Ehrlich, du bedeutest mir sehr viel.","Dürüst olmak gerekirse, sen benim için çok önemlisin.");
add("de","A2","Deyimler","Du bist mir wichtig","sen benim için değerlisin","Ausdruck","Vergiss nicht, du bist mir wichtig.","Unutma, sen benim için değerlisin.");
add("de","A2","Deyimler","Ich kann nicht ohne dich leben","sensiz yaşayamam","Ausdruck","Ehrlich, ich kann nicht ohne dich leben.","Dürüst olmak gerekirse, sensiz yaşayamam.");
add("de","A2","Deyimler","Du machst mich glücklich","beni mutlu ediyorsun","Ausdruck","Ehrlich, du machst mich jeden Tag glücklich.","Dürüst olmak gerekirse, beni her gün mutlu ediyorsun.");
add("de","A2","Deyimler","Bei dir fühle ich mich sicher","seninle güvende hissediyorum","Ausdruck","Ehrlich, bei dir fühle ich mich immer sicher.","Dürüst olmak gerekirse, seninle her zaman güvende hissediyorum.");
add("de","A2","Deyimler","Ich kann dir alles erzählen","sana her şeyi anlatabilirim","Ausdruck","Ehrlich, ich kann dir wirklich alles erzählen.","Dürüst olmak gerekirse, sana gerçekten her şeyi anlatabilirim.");
add("de","A2","Deyimler","Du verstehst mich am besten","beni en iyi sen anlıyorsun","Ausdruck","Ehrlich, du verstehst mich am allerbesten.","Dürüst olmak gerekirse, beni en iyi sen anlıyorsun.");
add("de","A2","Deyimler","Wir passen gut zusammen","biz iyi anlaşıyoruz (uyumluyuz)","Ausdruck","Ehrlich, wir passen wirklich gut zusammen.","Dürüst olmak gerekirse, gerçekten iyi uyumluyuz.");
add("de","A2","Deyimler","Wir sind ein gutes Team","iyi bir ekibiz","Ausdruck","Ehrlich, wir sind wirklich ein gutes Team.","Dürüst olmak gerekirse, gerçekten iyi bir ekibiz.");
add("de","A2","Deyimler","Wir verstehen uns gut","birbirimizi iyi anlıyoruz","Ausdruck","Ehrlich, wir verstehen uns wirklich gut.","Dürüst olmak gerekirse, gerçekten birbirimizi iyi anlıyoruz.");
add("de","A2","Deyimler","Wir haben viel gemeinsam","çok ortak yönümüz var","Ausdruck","Ehrlich, wir haben wirklich viel gemeinsam.","Dürüst olmak gerekirse, gerçekten çok ortak yönümüz var.");
add("de","A2","Deyimler","Wir sind uns sehr ähnlich","birbirimize çok benziyoruz","Ausdruck","Ehrlich, wir sind uns in vielem sehr ähnlich.","Dürüst olmak gerekirse, birçok konuda birbirimize çok benziyoruz.");
add("de","A2","Deyimler","Wir ergänzen uns gut","birbirimizi iyi tamamlıyoruz","Ausdruck","Ehrlich, wir ergänzen uns wirklich gut.","Dürüst olmak gerekirse, gerçekten birbirimizi iyi tamamlıyoruz.");
add("de","A2","Deyimler","Es ist kompliziert","karmaşık bir durum (ilişki)","Ausdruck","Ehrlich, es ist gerade etwas kompliziert.","Dürüst olmak gerekirse, şu an biraz karmaşık.");
add("de","A2","Deyimler","Wir haben uns getrennt","ayrıldık","Ausdruck","Ehrlich, wir haben uns letzten Monat getrennt.","Dürüst olmak gerekirse, geçen ay ayrıldık.");
add("de","A2","Deyimler","Wir sind wieder zusammen","tekrar birlikteyiz","Ausdruck","Ehrlich, wir sind seit letzter Woche wieder zusammen.","Dürüst olmak gerekirse, geçen haftadan beri tekrar birlikteyiz.");
add("de","A2","Deyimler","Wir haben uns gestritten","tartıştık","Ausdruck","Ehrlich, wir haben uns gestern gestritten.","Dürüst olmak gerekirse, dün tartıştık.");
add("de","A2","Deyimler","Wir haben uns wieder vertragen","barıştık","Ausdruck","Zum Glück haben wir uns wieder vertragen.","İyi ki barıştık.");
add("de","A2","Deyimler","Es tut mir leid für vorhin","az önceki için özür dilerim","Ausdruck","Es tut mir wirklich leid für vorhin.","Az önceki için gerçekten özür dilerim.");
add("de","A2","Deyimler","Verzeih mir bitte","beni affet lütfen","Ausdruck","Verzeih mir bitte, ich hab's nicht so gemeint.","Beni affet lütfen, öyle demek istemedim.");
add("de","A2","Deyimler","Ich vergebe dir","seni affediyorum","Ausdruck","Okay, ich vergebe dir diesmal.","Tamam, bu sefer seni affediyorum.");
add("de","A2","Deyimler","Lass es uns vergessen","hadi unutalım","Ausdruck","Komm, lass es uns einfach vergessen.","Hadi, bunu sadece unutalım.");
add("de","A2","Deyimler","Fangen wir neu an","yeniden başlayalım","Ausdruck","Komm, fangen wir einfach neu an.","Hadi, sadece yeniden başlayalım.");
add("de","A2","Deyimler","Lass uns Frieden schließen","hadi barışalım","Ausdruck","Komm, lass uns endlich Frieden schließen.","Hadi, sonunda barışalım.");
add("de","A2","Deyimler","Ich war zu voreilig","fazla acele ettim","Ausdruck","Ehrlich, ich war da zu voreilig.","Dürüst olmak gerekirse, orada fazla acele ettim.");
add("de","A2","Deyimler","Ich habe übertrieben","abarttım","Ausdruck","Ehrlich, ich habe wohl übertrieben.","Dürüst olmak gerekirse, herhalde abarttım.");
add("de","A2","Deyimler","So war das nicht gemeint","öyle demek istemedim","Ausdruck","Ehrlich, so war das nicht gemeint.","Dürüst olmak gerekirse, öyle demek istemedim.");
add("de","A2","Deyimler","Das kam falsch rüber","bu yanlış anlaşıldı","Ausdruck","Sorry, das kam wohl falsch rüber.","Üzgünüm, bu herhalde yanlış anlaşıldı.");
add("de","A2","Deyimler","Ich habe es falsch ausgedrückt","yanlış ifade ettim","Ausdruck","Sorry, ich habe es wohl falsch ausgedrückt.","Üzgünüm, herhalde yanlış ifade ettim.");
add("de","A2","Deyimler","Lass mich das erklären","bunu açıklamama izin ver","Ausdruck","Warte, lass mich das kurz erklären.","Bekle, bunu kısaca açıklamama izin ver.");
add("de","A2","Deyimler","Ich habe gute Nachrichten","iyi haberlerim var","Ausdruck","Hey, ich habe gute Nachrichten für dich!","Hey, senin için iyi haberlerim var!");
add("de","A2","Deyimler","Ich habe schlechte Nachrichten","kötü haberlerim var","Ausdruck","Leider habe ich schlechte Nachrichten.","Maalesef kötü haberlerim var.");
add("de","A2","Deyimler","Rate mal, was passiert ist","tahmin et ne oldu","Ausdruck","Rate mal, was heute passiert ist!","Tahmin et bugün ne oldu!");
add("de","A2","Deyimler","Du wirst es nicht glauben","buna inanmayacaksın","Ausdruck","Du wirst es einfach nicht glauben!","Buna basitçe inanmayacaksın!");
add("de","A2","Deyimler","Stell dir vor","hayal et / düşünsene","Ausdruck","Stell dir vor, ich habe gewonnen!","Düşünsene, kazandım!");
add("de","A2","Deyimler","Ich habe eine Ankündigung zu machen","bir duyurum var","Ausdruck","Leute, ich habe eine wichtige Ankündigung zu machen.","Millet, önemli bir duyurum var.");
add("de","A2","Deyimler","Es gibt Neuigkeiten","haberler var","Ausdruck","Es gibt große Neuigkeiten aus der Firma.","Şirketten büyük haberler var.");
add("de","A2","Deyimler","Weißt du schon das Neuste?","en son haberi biliyor musun?","Ausdruck","Weißt du schon das Neuste über ihn?","Onunla ilgili en son haberi biliyor musun?");
add("de","A2","Deyimler","Hast du das schon gehört?","bunu duydun mu?","Ausdruck","Hast du schon gehört, was passiert ist?","Ne olduğunu duydun mu?");
add("de","A2","Deyimler","Ich habe gehört, dass","duydum ki","Ausdruck","Ich habe gehört, dass er umzieht.","Taşındığını duydum.");
add("de","A2","Deyimler","Man sagt, dass","deniyor ki","Ausdruck","Man sagt, dass es bald schneit.","Yakında kar yağacağı söyleniyor.");
add("de","A2","Deyimler","Es heißt, dass","söyleniyor ki","Ausdruck","Es heißt, dass die Preise steigen werden.","Fiyatların artacağı söyleniyor.");
add("de","A2","Deyimler","Angeblich soll","söylentiye göre","Ausdruck","Angeblich soll er reich sein.","Söylentiye göre zenginmiş.");
add("de","A2","Deyimler","Das ist nur ein Gerücht","bu sadece bir söylenti","Ausdruck","Ehrlich, das ist wahrscheinlich nur ein Gerücht.","Dürüst olmak gerekirse, bu muhtemelen sadece bir söylenti.");
add("de","A2","Deyimler","Glaub nicht alles, was du hörst","duyduğun her şeye inanma","Ausdruck","Glaub bitte nicht alles, was du hörst.","Lütfen duyduğun her şeye inanma.");
add("de","A2","Deyimler","Woher weißt du das?","bunu nereden biliyorsun?","Ausdruck","Warte, woher weißt du das überhaupt?","Bekle, bunu nereden biliyorsun ki?");
add("de","A2","Deyimler","Wer hat dir das gesagt?","bunu sana kim söyledi?","Ausdruck","Sag mal, wer hat dir das gesagt?","Söyle bakalım, bunu sana kim söyledi?");
add("de","A2","Deyimler","Das behalte für dich","bunu kendine sakla","Ausdruck","Bitte behalte das für dich.","Lütfen bunu kendine sakla.");
add("de","A2","Deyimler","Sag es niemandem","kimseye söyleme","Ausdruck","Bitte sag es wirklich niemandem.","Lütfen bunu gerçekten kimseye söyleme.");
add("de","A2","Deyimler","Das bleibt unter uns","bu aramızda kalsın","Ausdruck","Okay, das bleibt aber unter uns.","Tamam ama bu aramızda kalsın.");
add("de","A2","Deyimler","Ich verrate kein Geheimnis","sır ele vermem","Ausdruck","Keine Sorge, ich verrate keine Geheimnisse.","Merak etme, sır ele vermem.");
add("de","A2","Deyimler","Ich kann Geheimnisse bewahren","sır saklayabilirim","Ausdruck","Ehrlich, ich kann sehr gut Geheimnisse bewahren.","Dürüst olmak gerekirse, çok iyi sır saklayabilirim.");
add("de","A2","Deyimler","Kann ich dir ein Geheimnis anvertrauen?","sana bir sır emanet edebilir miyim?","Ausdruck","Kann ich dir ein großes Geheimnis anvertrauen?","Sana büyük bir sır emanet edebilir miyim?");
add("de","A2","Deyimler","Ich habe dir etwas zu gestehen","sana itiraf edecek bir şeyim var","Ausdruck","Ehrlich, ich habe dir etwas zu gestehen.","Dürüst olmak gerekirse, sana itiraf edecek bir şeyim var.");
add("de","A2","Deyimler","Ich muss dir etwas sagen","sana bir şey söylemem gerekiyor","Ausdruck","Warte, ich muss dir etwas Wichtiges sagen.","Bekle, sana önemli bir şey söylemem gerekiyor.");
add("de","A2","Deyimler","Ich muss ehrlich sein","dürüst olmalıyım","Ausdruck","Ich muss ehrlich sein, es war schwer.","Dürüst olmalıyım, zordu.");
add("de","A2","Deyimler","Um ehrlich zu sein","açıkçası","Ausdruck","Um ehrlich zu sein, ich mag das nicht.","Açıkçası, bunu sevmiyorum.");
add("de","A2","Deyimler","Um die Wahrheit zu sagen","gerçeği söylemek gerekirse","Ausdruck","Um die Wahrheit zu sagen, war ich müde.","Gerçeği söylemek gerekirse, yorgundum.");
add("de","A2","Deyimler","Ich will nicht lügen","yalan söylemek istemiyorum","Ausdruck","Ich will nicht lügen, es war schwer.","Yalan söylemek istemiyorum, zordu.");
add("de","A2","Deyimler","Sag mir die Wahrheit","bana gerçeği söyle","Ausdruck","Bitte sag mir einfach die Wahrheit.","Lütfen bana sadece gerçeği söyle.");
add("de","A2","Deyimler","Ich bin so aufgeregt","çok heyecanlıyım","Ausdruck","Ehrlich, ich bin so aufgeregt für morgen.","Dürüst olmak gerekirse, yarın için çok heyecanlıyım.");
add("de","A2","Deyimler","Ich kann kaum still sitzen","yerimde duramıyorum","Ausdruck","Ehrlich, ich kann vor Aufregung kaum still sitzen.","Dürüst olmak gerekirse, heyecandan yerimde duramıyorum.");
add("de","A2","Deyimler","Mein Herz schlägt schnell","kalbim hızlı atıyor","Ausdruck","Ehrlich, mein Herz schlägt gerade so schnell.","Dürüst olmak gerekirse, kalbim şu an çok hızlı atıyor.");
add("de","A2","Deyimler","Ich habe Schmetterlinge im Bauch","içimde kelebekler uçuşuyor","Ausdruck","Ehrlich, ich habe gerade Schmetterlinge im Bauch.","Dürüst olmak gerekirse, şu an içimde kelebekler uçuşuyor.");
add("de","A2","Deyimler","Mir wird ganz anders","fenalaşıyorum","Ausdruck","Ehrlich, mir wird ganz anders bei diesem Gedanken.","Dürüst olmak gerekirse, bu düşünceyle fenalaşıyorum.");
add("de","A2","Deyimler","Mir läuft es kalt den Rücken runter","sırtımdan soğuk terler döküldü","Ausdruck","Ehrlich, mir lief es kalt den Rücken runter.","Dürüst olmak gerekirse, sırtımdan soğuk terler döküldü.");
add("de","A2","Deyimler","Ich habe eine Gänsehaut","tüylerim diken diken oldu","Ausdruck","Ehrlich, ich habe gerade eine Gänsehaut.","Dürüst olmak gerekirse, şu an tüylerim diken diken oldu.");
add("de","A2","Deyimler","Das jagt mir Angst ein","bu beni korkutuyor","Ausdruck","Ehrlich, dieser Film jagt mir richtig Angst ein.","Dürüst olmak gerekirse, bu film beni gerçekten korkutuyor.");
add("de","A2","Deyimler","Ich habe fürchterliche Angst","çok korkuyorum","Ausdruck","Ehrlich, ich habe fürchterliche Angst vor Spinnen.","Dürüst olmak gerekirse, örümceklerden çok korkuyorum.");
add("de","A2","Deyimler","Das macht mir Sorgen","bu beni endişelendiriyor","Ausdruck","Ehrlich, das macht mir wirklich Sorgen.","Dürüst olmak gerekirse, bu beni gerçekten endişelendiriyor.");
add("de","A2","Deyimler","Ich mache mir Sorgen um dich","senin için endişeleniyorum","Ausdruck","Ehrlich, ich mache mir wirklich Sorgen um dich.","Dürüst olmak gerekirse, senin için gerçekten endişeleniyorum.");
add("de","A2","Deyimler","Sei unbesorgt","endişelenme (resmi)","Ausdruck","Sei unbesorgt, alles wird gut gehen.","Endişelenme, her şey iyi gidecek.");
add("de","A2","Deyimler","Das nervt mich total","bu beni gerçekten sinir ediyor","Ausdruck","Ehrlich, das nervt mich schon den ganzen Tag.","Dürüst olmak gerekirse, tüm gün beni sinir ediyor.");
add("de","A2","Deyimler","Das geht mir auf die Nerven","bu sinirimi bozuyor","Ausdruck","Ehrlich, das geht mir wirklich auf die Nerven.","Dürüst olmak gerekirse, bu gerçekten sinirimi bozuyor.");
add("de","A2","Deyimler","Ich habe die Nase voll","bıktım usandım","Ausdruck","Ehrlich, ich habe langsam die Nase voll davon.","Dürüst olmak gerekirse, yavaş yavaş bundan bıktım usandım.");
add("de","A2","Deyimler","Mir platzt gleich der Kragen","tepem atacak","Ausdruck","Ehrlich, mir platzt gleich der Kragen.","Dürüst olmak gerekirse, az kalsın tepem atacaktı.");
add("de","A2","Deyimler","Ich bin außer mir","kendimden geçmiş durumdayım (öfkeden)","Ausdruck","Ehrlich, ich bin gerade völlig außer mir.","Dürüst olmak gerekirse, şu an tamamen kendimden geçmiş durumdayım.");
add("de","A2","Deyimler","Ich koche vor Wut","öfkeden kaynıyorum","Ausdruck","Ehrlich, ich koche gerade vor Wut.","Dürüst olmak gerekirse, şu an öfkeden kaynıyorum.");
add("de","A2","Deyimler","Reg dich ab","sakinleş (informal)","Ausdruck","Komm schon, reg dich mal ab.","Hadi ama, biraz sakinleş.");
add("de","A2","Deyimler","Tief durchatmen","derin nefes al","Ausdruck","Tief durchatmen, alles wird gut.","Derin nefes al, her şey yoluna girecek.");
add("de","A2","Deyimler","Zähl bis zehn","ona kadar say","Ausdruck","Zähl einfach bis zehn und beruhig dich.","Sadece ona kadar say ve sakinleş.");
add("de","A2","Deyimler","Lass es raus","içini dök","Ausdruck","Lass es einfach raus, du fühlst dich besser.","Sadece içini dök, kendini daha iyi hissedersin.");
add("de","A2","Deyimler","Rede dich frei","gönlünce konuş / rahatla","Ausdruck","Rede dich einfach frei, ich höre zu.","Sadece rahatça konuş, dinliyorum.");
add("de","A2","Deyimler","Es tut gut, das zu sagen","bunu söylemek iyi geldi","Ausdruck","Ehrlich, es tut gut, das endlich zu sagen.","Dürüst olmak gerekirse, sonunda bunu söylemek iyi geldi.");
add("de","A2","Deyimler","Mir fällt ein Stein vom Herzen","içim rahatladı","Ausdruck","Ehrlich, mir fällt gerade ein Stein vom Herzen.","Dürüst olmak gerekirse, şu an içim rahatladı.");
add("de","A2","Deyimler","Endlich kann ich aufatmen","sonunda rahat bir nefes alabilirim","Ausdruck","Endlich kann ich wieder richtig aufatmen.","Sonunda tekrar rahat bir nefes alabilirim.");
add("de","A2","Deyimler","Puh, das war knapp","öf, ucu ucuna oldu","Ausdruck","Puh, das war wirklich sehr knapp.","Öf, bu gerçekten çok ucu ucuna oldu.");
add("de","A2","Deyimler","Gott sei Dank","Allah'a şükür","Ausdruck","Gott sei Dank ist nichts passiert.","Allah'a şükür bir şey olmadı.");
add("de","A2","Deyimler","Zum Glück ist nichts passiert","iyi ki bir şey olmadı","Ausdruck","Zum Glück ist niemandem etwas passiert.","İyi ki kimseye bir şey olmadı.");
add("de","A2","Deyimler","Wir hatten Glück im Unglück","talihsizlikte şanslıydık","Ausdruck","Ehrlich, wir hatten wirklich Glück im Unglück.","Dürüst olmak gerekirse, gerçekten talihsizlikte şanslıydık.");
add("de","A2","Deyimler","Wie fühlst du dich dabei?","bu konuda nasıl hissediyorsun?","Ausdruck","Sag mal, wie fühlst du dich dabei?","Söyle bakalım, bu konuda nasıl hissediyorsun?");
add("de","A2","Deyimler","Ich fühle mich komisch dabei","bu konuda garip hissediyorum","Ausdruck","Ehrlich, ich fühle mich etwas komisch dabei.","Dürüst olmak gerekirse, bu konuda biraz garip hissediyorum.");
add("de","A2","Deyimler","Ich fühle mich wohl dabei","bu konuda rahatım","Ausdruck","Ehrlich, ich fühle mich damit ziemlich wohl.","Dürüst olmak gerekirse, bu konuda oldukça rahatım.");
add("de","A2","Deyimler","Ich fühle mich unwohl dabei","bu konuda rahatsızım","Ausdruck","Ehrlich, ich fühle mich damit etwas unwohl.","Dürüst olmak gerekirse, bu konuda biraz rahatsızım.");
add("de","A2","Deyimler","Das fühlt sich richtig an","bu doğru hissettiriyor","Ausdruck","Ehrlich, das fühlt sich einfach richtig an.","Dürüst olmak gerekirse, bu basitçe doğru hissettiriyor.");
add("de","A2","Deyimler","Das fühlt sich falsch an","bu yanlış hissettiriyor","Ausdruck","Ehrlich, das fühlt sich irgendwie falsch an.","Dürüst olmak gerekirse, bu bir şekilde yanlış hissettiriyor.");
add("de","A2","Deyimler","Irgendetwas stimmt nicht","bir şeyler ters gidiyor","Ausdruck","Ehrlich, irgendetwas stimmt hier nicht.","Dürüst olmak gerekirse, burada bir şeyler ters gidiyor.");
add("de","A2","Deyimler","Etwas fühlt sich seltsam an","bir şeyler garip hissettiriyor","Ausdruck","Ehrlich, etwas fühlt sich hier seltsam an.","Dürüst olmak gerekirse, burada bir şeyler garip hissettiriyor.");
add("de","A2","Deyimler","Ich kann es nicht erklären","bunu açıklayamıyorum","Ausdruck","Ehrlich, ich kann es einfach nicht erklären.","Dürüst olmak gerekirse, bunu basitçe açıklayamıyorum.");
add("de","A2","Deyimler","Ich habe keine Erklärung dafür","bunun için bir açıklamam yok","Ausdruck","Ehrlich, ich habe wirklich keine Erklärung dafür.","Dürüst olmak gerekirse, bunun için gerçekten bir açıklamam yok.");
add("de","A2","Deyimler","Es gibt keine logische Erklärung","mantıklı bir açıklaması yok","Ausdruck","Ehrlich, es gibt keine logische Erklärung dafür.","Dürüst olmak gerekirse, bunun mantıklı bir açıklaması yok.");
add("de","A2","Deyimler","Das ergibt keinen Sinn","bunun bir anlamı yok","Ausdruck","Ehrlich, das ergibt für mich keinen Sinn.","Dürüst olmak gerekirse, bunun benim için bir anlamı yok.");
add("de","A2","Deyimler","Jetzt ergibt alles Sinn","şimdi her şey anlam kazandı","Ausdruck","Ah, jetzt ergibt endlich alles Sinn!","Ah, şimdi sonunda her şey anlam kazandı!");
add("de","A2","Deyimler","Jetzt verstehe ich es","şimdi anlıyorum","Ausdruck","Ah, jetzt verstehe ich es endlich!","Ah, şimdi sonunda anlıyorum!");
add("de","A2","Deyimler","Der Groschen ist gefallen","kafamda şimşek çaktı","Ausdruck","Endlich, der Groschen ist gefallen!","Sonunda, kafamda şimşek çaktı!");
add("de","A2","Deyimler","Mir geht ein Licht auf","gözüm açıldı","Ausdruck","Ah, mir geht gerade ein Licht auf!","Ah, şu an gözüm açılıyor!");
add("de","A2","Deyimler","Ich habe es endlich kapiert","sonunda anladım","Ausdruck","Puh, ich habe es endlich kapiert!","Öf, sonunda anladım!");
add("de","A2","Deyimler","Es fällt bei mir der Cent","kuruş düştü (anladım)","Ausdruck","Ah, jetzt fällt bei mir der Cent!","Ah, şimdi kuruş düştü!");
add("de","A2","Deyimler","Ich stehe total auf dem Schlauch","hiçbir şey anlamıyorum","Ausdruck","Ehrlich, ich stehe hier gerade total auf dem Schlauch.","Dürüst olmak gerekirse, şu an burada hiçbir şey anlamıyorum.");
add("de","A2","Deyimler","Ich blicke da nicht durch","bunu anlayamıyorum","Ausdruck","Ehrlich, ich blicke da einfach nicht durch.","Dürüst olmak gerekirse, bunu basitçe anlayamıyorum.");
add("de","A2","Deyimler","Kannst du das einfacher erklären?","bunu daha basit açıklayabilir misin?","Ausdruck","Kannst du mir das bitte einfacher erklären?","Lütfen bunu bana daha basit açıklayabilir misin?");
add("de","A2","Deyimler","Erklär es mir wie einem Kind","bana çocuğa anlatır gibi anlat","Ausdruck","Bitte erklär es mir wie einem Kind.","Lütfen bana çocuğa anlatır gibi anlat.");
add("de","A2","Deyimler","In einfachen Worten","basit bir dille","Ausdruck","In einfachen Worten, es geht um Geld.","Basit bir dille, konu para.");
add("de","A2","Deyimler","Grob gesagt","kabaca söylemek gerekirse","Ausdruck","Grob gesagt, das ist die Idee.","Kabaca söylemek gerekirse, fikir bu.");
add("de","A2","Deyimler","Genauer gesagt","daha kesin söylemek gerekirse","Ausdruck","Genauer gesagt, es war letzten Montag.","Daha kesin söylemek gerekirse, geçen pazartesiydi.");
add("de","A2","Deyimler","Um genau zu sein","tam olarak söylemek gerekirse","Ausdruck","Um genau zu sein, es waren fünf Minuten.","Tam olarak söylemek gerekirse, beş dakikaydı.");
add("de","A2","Deyimler","Sagen wir mal so","şöyle söyleyelim","Ausdruck","Sagen wir mal so, es war nicht einfach.","Şöyle söyleyelim, kolay değildi.");
add("de","A2","Deyimler","Wie soll ich sagen","nasıl söylesem","Ausdruck","Wie soll ich sagen, es war anders.","Nasıl söylesem, farklıydı.");
add("de","A2","Deyimler","Wie soll ich das ausdrücken","bunu nasıl ifade etsem","Ausdruck","Wie soll ich das nur ausdrücken?","Bunu nasıl ifade etsem ki?");
add("de","A2","Deyimler","Ich weiß nicht, wie ich anfangen soll","nasıl başlayacağımı bilmiyorum","Ausdruck","Ehrlich, ich weiß nicht, wie ich anfangen soll.","Dürüst olmak gerekirse, nasıl başlayacağımı bilmiyorum.");
add("de","A2","Deyimler","Wo warst du die ganze Zeit?","bunca zaman neredeydin?","Ausdruck","Wo warst du denn die ganze Zeit?","Bunca zaman neredeydin ki?");
add("de","A2","Deyimler","Was machst du hier?","burada ne yapıyorsun?","Ausdruck","Hey, was machst du denn hier?","Hey, burada ne yapıyorsun ki?");
add("de","A2","Deyimler","Was machst du gerade?","şu an ne yapıyorsun?","Ausdruck","Hey, was machst du gerade so?","Hey, şu an ne yapıyorsun?");
add("de","A2","Deyimler","Womit beschäftigst du dich?","neyle uğraşıyorsun?","Ausdruck","Sag mal, womit beschäftigst du dich diese Woche?","Söyle bakalım, bu hafta neyle uğraşıyorsun?");
add("de","A2","Deyimler","Was ist dein Beruf?","mesleğin nedir?","Ausdruck","Entschuldigung, was ist dein Beruf?","Affedersin, mesleğin nedir?");
add("de","A2","Deyimler","Was studierst du?","ne okuyorsun?","Ausdruck","Sag mal, was studierst du eigentlich?","Söyle bakalım, aslında ne okuyorsun?");
add("de","A2","Deyimler","Wo hast du studiert?","nerede okudun?","Ausdruck","Entschuldigung, wo hast du studiert?","Affedersin, nerede okudun?");
add("de","A2","Deyimler","Seit wann arbeitest du dort?","orada ne zamandan beri çalışıyorsun?","Ausdruck","Sag mal, seit wann arbeitest du schon dort?","Söyle bakalım, orada ne zamandan beri çalışıyorsun?");
add("de","A2","Deyimler","Wie lange machst du das schon?","bunu ne zamandır yapıyorsun?","Ausdruck","Sag mal, wie lange machst du das schon?","Söyle bakalım, bunu ne zamandır yapıyorsun?");
add("de","A2","Deyimler","Seit wann kennt ihr euch?","birbirinizi ne zamandan beri tanıyorsunuz?","Ausdruck","Sag mal, seit wann kennt ihr euch beide?","Söyle bakalım, ikiniz birbirinizi ne zamandan beri tanıyorsunuz?");
add("de","A2","Deyimler","Wie habt ihr euch kennengelernt?","birbirinizle nasıl tanıştınız?","Ausdruck","Erzähl mal, wie habt ihr euch kennengelernt?","Anlat bakalım, birbirinizle nasıl tanıştınız?");
add("de","A2","Deyimler","Wir haben uns über Freunde kennengelernt","arkadaşlar aracılığıyla tanıştık","Ausdruck","Wir haben uns eigentlich über Freunde kennengelernt.","Aslında arkadaşlar aracılığıyla tanıştık.");
add("de","A2","Deyimler","Wo bist du aufgewachsen?","nerede büyüdün?","Ausdruck","Sag mal, wo bist du eigentlich aufgewachsen?","Söyle bakalım, aslında nerede büyüdün?");
add("de","A2","Deyimler","Wo bist du geboren?","nerede doğdun?","Ausdruck","Entschuldigung, wo bist du geboren?","Affedersin, nerede doğdun?");
add("de","A2","Deyimler","Wie alt bist du geworden?","kaç yaşına girdin?","Ausdruck","Sag mal, wie alt bist du jetzt geworden?","Söyle bakalım, şimdi kaç yaşına girdin?");
add("de","A2","Deyimler","Wann hast du Geburtstag?","doğum günün ne zaman?","Ausdruck","Entschuldigung, wann hast du eigentlich Geburtstag?","Affedersin, aslında doğum günün ne zaman?");
add("de","A2","Deyimler","Was schenkst du ihm?","ona ne hediye ediyorsun?","Ausdruck","Sag mal, was schenkst du ihm zum Geburtstag?","Söyle bakalım, doğum günü için ona ne hediye ediyorsun?");
add("de","A2","Deyimler","Hast du schon ein Geschenk?","zaten bir hediyen var mı?","Ausdruck","Sag mal, hast du für sie schon ein Geschenk?","Söyle bakalım, onun için zaten bir hediyen var mı?");
add("de","A2","Deyimler","Ich weiß nicht, was ich schenken soll","ne hediye edeceğimi bilmiyorum","Ausdruck","Ehrlich, ich weiß gar nicht, was ich schenken soll.","Dürüst olmak gerekirse, ne hediye edeceğimi hiç bilmiyorum.");
add("de","A2","Deyimler","Hast du eine Geschenkidee?","hediye fikrin var mı?","Ausdruck","Hast du vielleicht eine gute Geschenkidee?","Belki iyi bir hediye fikrin var mı?");
add("de","A2","Deyimler","Das wird ihm bestimmt gefallen","bu ona kesinlikle hoşuna gidecek","Ausdruck","Ehrlich, das wird ihm bestimmt sehr gefallen.","Dürüst olmak gerekirse, bu ona kesinlikle çok hoşuna gidecek.");
add("de","A2","Deyimler","Ich hoffe, es gefällt dir","umarım hoşuna gider","Ausdruck","Hier, ich hoffe, es gefällt dir sehr.","Al, umarım çok hoşuna gider.");
add("de","A2","Deyimler","Das ist genau, was ich wollte","tam istediğim şey buydu","Ausdruck","Wow, das ist genau, was ich wollte!","Vay, tam istediğim şey buydu!");
add("de","A2","Deyimler","Das hätte ich mir nie gekauft","bunu kendime asla almazdım","Ausdruck","Danke, das hätte ich mir nie selbst gekauft.","Teşekkürler, bunu kendime asla almazdım.");
add("de","A2","Deyimler","Woher wusstest du das?","bunu nereden biliyordun?","Ausdruck","Wow, woher wusstest du das nur?","Vay, bunu nereden biliyordun ki?");
add("de","A2","Deyimler","Du kennst mich einfach gut","beni gerçekten iyi tanıyorsun","Ausdruck","Ehrlich, du kennst mich einfach so gut.","Dürüst olmak gerekirse, beni gerçekten iyi tanıyorsun.");
add("de","A2","Deyimler","Das war lieb von dir","bu senden çok tatlıydı","Ausdruck","Danke, das war wirklich lieb von dir.","Teşekkürler, bu senden gerçekten çok tatlıydı.");
add("de","A2","Deyimler","Du hättest das nicht tun müssen","bunu yapmana gerek yoktu","Ausdruck","Danke, aber du hättest das nicht tun müssen.","Teşekkürler ama bunu yapmana gerek yoktu.");
add("de","A2","Deyimler","Das war nicht nötig","buna gerek yoktu","Ausdruck","Danke, aber das war wirklich nicht nötig.","Teşekkürler ama buna gerçekten gerek yoktu.");
add("de","A2","Deyimler","Ich habe einen Vorschlag","bir önerim var","Ausdruck","Leute, ich habe einen kleinen Vorschlag.","Millet, küçük bir önerim var.");
add("de","A2","Deyimler","Was haltet ihr davon?","siz ne düşünüyorsunuz?","Ausdruck","Also, was haltet ihr alle davon?","Peki, hepiniz ne düşünüyorsunuz?");
add("de","A2","Deyimler","Ich bin für diesen Vorschlag","bu öneriye taraftarım","Ausdruck","Ehrlich, ich bin voll für diesen Vorschlag.","Dürüst olmak gerekirse, tamamen bu öneriye taraftarım.");
add("de","A2","Deyimler","Lasst uns darüber abstimmen","hadi bunu oylayalım","Ausdruck","Okay, lasst uns einfach darüber abstimmen.","Tamam, hadi sadece bunu oylayalım.");
add("de","A2","Deyimler","Die Mehrheit entscheidet","çoğunluk karar verir","Ausdruck","Okay, die Mehrheit entscheidet dann.","Tamam, o zaman çoğunluk karar verir.");
add("de","A2","Deyimler","Wir sind uns alle einig","hepimiz hemfikiriz","Ausdruck","Gut, wir sind uns dann alle einig.","İyi, o zaman hepimiz hemfikiriz.");
add("de","A2","Deyimler","Da gehen die Meinungen auseinander","bu konuda görüşler ayrılıyor","Ausdruck","Ehrlich, da gehen die Meinungen ziemlich auseinander.","Dürüst olmak gerekirse, bu konuda görüşler oldukça ayrılıyor.");
add("de","A2","Deyimler","Jeder hat seine eigene Meinung","herkesin kendi görüşü var","Ausdruck","Nun ja, jeder hat da seine eigene Meinung.","Şey, herkesin bu konuda kendi görüşü var.");
add("de","A2","Deyimler","Lass uns das Thema wechseln","hadi konuyu değiştirelim","Ausdruck","Okay, lass uns lieber das Thema wechseln.","Tamam, hadi konuyu değiştirelim daha iyi.");
add("de","A2","Deyimler","Zurück zum Thema","konuya dönelim","Ausdruck","Okay, zurück zum eigentlichen Thema.","Tamam, asıl konuya dönelim.");
add("de","A2","Deyimler","Das führt zu weit","bu konuyu çok uzatır","Ausdruck","Lass uns aufhören, das führt zu weit.","Bırakalım, bu konuyu çok uzatır.");
add("de","A2","Deyimler","Das steht nicht zur Debatte","bu tartışmaya açık değil","Ausdruck","Sorry, aber das steht nicht zur Debatte.","Üzgünüm ama bu tartışmaya açık değil.");
add("de","A2","Deyimler","Kommen wir zum Punkt","asıl konuya gelelim","Ausdruck","Okay, kommen wir jetzt zum Punkt.","Tamam, şimdi asıl konuya gelelim.");
add("de","A2","Deyimler","Was ist der eigentliche Punkt?","asıl mesele nedir?","Ausdruck","Sag mal, was ist eigentlich der Punkt?","Söyle bakalım, aslında mesele nedir?");
add("de","A2","Deyimler","Der Punkt ist folgender","mesele şu","Ausdruck","Okay, der Punkt ist einfach folgender.","Tamam, mesele basitçe şu.");
add("de","A2","Deyimler","Darauf will ich hinaus","söylemek istediğim bu","Ausdruck","Genau darauf will ich hinaus.","Tam olarak söylemek istediğim bu.");
add("de","A2","Deyimler","Verstehst du, worauf ich hinauswill?","ne demek istediğimi anlıyor musun?","Ausdruck","Sag mal, verstehst du, worauf ich hinauswill?","Söyle bakalım, ne demek istediğimi anlıyor musun?");
add("de","A2","Deyimler","Ich glaube, du verstehst mich falsch","sanırım beni yanlış anlıyorsun","Ausdruck","Ehrlich, ich glaube, du verstehst mich hier falsch.","Dürüst olmak gerekirse, sanırım burada beni yanlış anlıyorsun.");
add("de","A2","Deyimler","So habe ich das nicht gemeint","öyle demek istememiştim","Ausdruck","Sorry, so habe ich das wirklich nicht gemeint.","Üzgünüm, öyle demek gerçekten istememiştim.");
add("de","A2","Deyimler","Lass mich das anders formulieren","bunu farklı ifade edeyim","Ausdruck","Okay, lass mich das einfach anders formulieren.","Tamam, sadece bunu farklı ifade edeyim.");
add("de","A2","Deyimler","Anders ausgedrückt","başka türlü ifade edilirse","Ausdruck","Anders ausgedrückt, es ist kompliziert.","Başka türlü ifade edilirse, karmaşık.");
add("de","A2","Deyimler","Was ich sagen will, ist","söylemek istediğim şu ki","Ausdruck","Was ich eigentlich sagen will, ist einfach folgendes.","Aslında söylemek istediğim basitçe şu.");
add("de","A2","Deyimler","Ich möchte nur klarstellen","sadece açıklığa kavuşturmak istiyorum","Ausdruck","Ich möchte hier nur kurz etwas klarstellen.","Burada sadece kısaca bir şeyi açıklığa kavuşturmak istiyorum.");
add("de","A2","Deyimler","Zur Klarstellung","açıklık getirmek için","Ausdruck","Nur zur Klarstellung, ich meinte es anders.","Sadece açıklık getirmek için, farklı demek istemiştim.");
add("de","A2","Deyimler","Ich will nichts falsch verstanden wissen","yanlış anlaşılmasını istemiyorum","Ausdruck","Ehrlich, ich will hier nichts falsch verstanden wissen.","Dürüst olmak gerekirse, burada yanlış anlaşılmasını istemiyorum.");
add("de","A2","Deyimler","Bitte versteh mich nicht falsch","lütfen beni yanlış anlama","Ausdruck","Bitte versteh mich hier nicht falsch.","Lütfen beni burada yanlış anlama.");
add("de","A2","Deyimler","Nichts für ungut","gücenmece yok","Ausdruck","Nichts für ungut, aber das stimmt nicht.","Gücenmece yok ama bu doğru değil.");
add("de","A2","Deyimler","Wir sind fast da","neredeyse geldik","Ausdruck","Keine Sorge, wir sind fast da.","Merak etme, neredeyse geldik.");
add("de","A2","Deyimler","Wie weit ist es noch?","daha ne kadar var?","Ausdruck","Sag mal, wie weit ist es denn noch?","Söyle bakalım, daha ne kadar var ki?");
add("de","A2","Deyimler","Wir haben es geschafft","başardık","Ausdruck","Endlich, wir haben es geschafft!","Sonunda, başardık!");
add("de","A2","Deyimler","Das haben wir gut hinbekommen","bunu iyi becerdik","Ausdruck","Ehrlich, das haben wir wirklich gut hinbekommen.","Dürüst olmak gerekirse, bunu gerçekten iyi becerdik.");
add("de","A2","Deyimler","Das war Teamarbeit","bu takım çalışmasıydı","Ausdruck","Ehrlich, das war reine Teamarbeit.","Dürüst olmak gerekirse, bu saf takım çalışmasıydı.");
add("de","A2","Deyimler","Ohne dich hätten wir es nicht geschafft","sensiz başaramazdık","Ausdruck","Ehrlich, ohne dich hätten wir es nie geschafft.","Dürüst olmak gerekirse, sensiz asla başaramazdık.");
add("de","A2","Deyimler","Das verdanken wir dir","bunu sana borçluyuz","Ausdruck","Ehrlich, das verdanken wir ganz dir.","Dürüst olmak gerekirse, bunu tamamen sana borçluyuz.");
add("de","A2","Deyimler","Wir sind ein tolles Team","harika bir ekibiz","Ausdruck","Ehrlich, wir sind wirklich ein tolles Team.","Dürüst olmak gerekirse, gerçekten harika bir ekibiz.");
add("de","A2","Deyimler","Darauf können wir stolz sein","bununla gurur duyabiliriz","Ausdruck","Ehrlich, darauf können wir alle stolz sein.","Dürüst olmak gerekirse, hepimiz bununla gurur duyabiliriz.");
add("de","A2","Deyimler","Das haben wir uns verdient","bunu hak ettik","Ausdruck","Ehrlich, das haben wir uns wirklich verdient.","Dürüst olmak gerekirse, bunu gerçekten hak ettik.");
add("de","A2","Deyimler","Jetzt können wir feiern","şimdi kutlayabiliriz","Ausdruck","Endlich, jetzt können wir richtig feiern!","Sonunda, şimdi gerçekten kutlayabiliriz!");
add("de","A2","Deyimler","Das müssen wir feiern","bunu kutlamalıyız","Ausdruck","Ehrlich, das müssen wir unbedingt feiern.","Dürüst olmak gerekirse, bunu mutlaka kutlamalıyız.");
add("de","A2","Deyimler","Lasst uns anstoßen","hadi kadeh kaldıralım","Ausdruck","Kommt, lasst uns darauf anstoßen!","Gelin, buna kadeh kaldıralım!");
add("de","A2","Deyimler","Auf uns","bize (kadeh kaldırırken)","Ausdruck","Auf uns und unseren Erfolg!","Bize ve başarımıza!");
add("de","A2","Deyimler","Auf die Zukunft","geleceğe","Ausdruck","Auf die Zukunft und neue Anfänge!","Geleceğe ve yeni başlangıçlara!");
add("de","A2","Deyimler","Das war es wert","buna değdi","Ausdruck","Ehrlich, jede Minute war es wert.","Dürüst olmak gerekirse, her dakikasına değdi.");
add("de","A2","Deyimler","Es hat sich alles gelohnt","her şey buna değdi","Ausdruck","Ehrlich, es hat sich am Ende alles gelohnt.","Dürüst olmak gerekirse, sonunda her şey buna değdi.");
add("de","A2","Deyimler","Alle Mühe hat sich gelohnt","tüm çaba buna değdi","Ausdruck","Ehrlich, all die Mühe hat sich wirklich gelohnt.","Dürüst olmak gerekirse, tüm çaba gerçekten buna değdi.");
add("de","A2","Deyimler","Das war die harte Arbeit wert","bu sıkı çalışmaya değdi","Ausdruck","Ehrlich, das war die ganze harte Arbeit wert.","Dürüst olmak gerekirse, bu tüm sıkı çalışmaya değdi.");
add("de","A2","Deyimler","Wir haben unser Ziel erreicht","hedefimize ulaştık","Ausdruck","Endlich, wir haben unser Ziel erreicht!","Sonunda, hedefimize ulaştık!");
add("de","A2","Deyimler","Jetzt setzen wir uns ein neues Ziel","şimdi yeni bir hedef koyalım","Ausdruck","Okay, jetzt setzen wir uns ein neues Ziel.","Tamam, şimdi yeni bir hedef koyalım.");
add("de","A2","Deyimler","Wir sind noch nicht fertig","henüz bitirmedik","Ausdruck","Ehrlich, wir sind hier noch nicht fertig.","Dürüst olmak gerekirse, burada henüz bitirmedik.");
add("de","A2","Deyimler","Es gibt noch viel zu tun","hâlâ yapılacak çok şey var","Ausdruck","Ehrlich, es gibt hier noch viel zu tun.","Dürüst olmak gerekirse, burada hâlâ yapılacak çok şey var.");
add("de","A2","Deyimler","Wir sind auf einem guten Weg","doğru yoldayız","Ausdruck","Ehrlich, wir sind wirklich auf einem guten Weg.","Dürüst olmak gerekirse, gerçekten doğru yoldayız.");
add("de","A2","Deyimler","Wir kommen gut voran","iyi ilerliyoruz","Ausdruck","Ehrlich, wir kommen wirklich gut voran.","Dürüst olmak gerekirse, gerçekten iyi ilerliyoruz.");
add("de","A2","Deyimler","Es bewegt sich etwas","bir şeyler ilerliyor","Ausdruck","Endlich, es bewegt sich hier etwas!","Sonunda, burada bir şeyler ilerliyor!");
add("de","A2","Deyimler","Wir haben große Fortschritte gemacht","büyük ilerleme kaydettik","Ausdruck","Ehrlich, wir haben diese Woche große Fortschritte gemacht.","Dürüst olmak gerekirse, bu hafta büyük ilerleme kaydettik.");
add("de","A2","Deyimler","Kannst du mir kurz zuhören?","beni kısaca dinleyebilir misin?","Ausdruck","Kannst du mir bitte kurz zuhören?","Lütfen beni kısaca dinleyebilir misin?");
add("de","A2","Deyimler","Hör mir mal zu","beni bir dinle","Ausdruck","Hör mir mal kurz zu, bitte.","Lütfen beni bir kısaca dinle.");
add("de","A2","Deyimler","Ich höre dir zu","seni dinliyorum","Ausdruck","Klar, ich höre dir aufmerksam zu.","Tabii, seni dikkatle dinliyorum.");
add("de","A2","Deyimler","Bist du noch dran?","hâlâ orada mısın?","Ausdruck","Hallo, bist du noch dran?","Alo, hâlâ orada mısın?");
add("de","A2","Deyimler","Ich höre dich schlecht","seni kötü duyuyorum","Ausdruck","Sorry, ich höre dich gerade schlecht.","Üzgünüm, seni şu an kötü duyuyorum.");
add("de","A2","Deyimler","Die Verbindung ist schlecht","bağlantı kötü","Ausdruck","Sorry, die Verbindung ist hier schlecht.","Üzgünüm, buradaki bağlantı kötü.");
add("de","A2","Deyimler","Ich rufe dich zurück","seni geri arayacağım","Ausdruck","Sorry, ich rufe dich gleich zurück.","Üzgünüm, seni hemen geri arayacağım.");
add("de","A2","Deyimler","Kannst du das lauter sagen?","bunu daha yüksek sesle söyleyebilir misin?","Ausdruck","Entschuldigung, kannst du das etwas lauter sagen?","Affedersin, bunu biraz daha yüksek sesle söyleyebilir misin?");
add("de","A2","Deyimler","Sprich bitte etwas leiser","lütfen biraz daha sessiz konuş","Ausdruck","Sprich bitte etwas leiser, die Kinder schlafen.","Lütfen biraz daha sessiz konuş, çocuklar uyuyor.");
add("de","A2","Deyimler","Ich kann dich kaum hören","seni zor duyuyorum","Ausdruck","Sorry, ich kann dich hier kaum hören.","Üzgünüm, burada seni zor duyuyorum.");
add("de","A2","Deyimler","Kannst du das Video anmachen?","kamerayı açabilir misin?","Ausdruck","Kannst du bitte kurz das Video anmachen?","Lütfen kısaca kamerayı açabilir misin?");
add("de","A2","Deyimler","Dein Bild ist eingefroren","görüntün donmuş","Ausdruck","Sorry, dein Bild ist gerade eingefroren.","Üzgünüm, görüntün şu an donmuş.");
add("de","A2","Deyimler","Kannst du dich noch mal einwählen?","tekrar bağlanabilir misin?","Ausdruck","Kannst du dich bitte noch mal einwählen?","Lütfen tekrar bağlanabilir misin?");
add("de","A2","Deyimler","Wir haben dich verloren","seni kaybettik (bağlantı)","Ausdruck","Sorry, wir haben dich kurz verloren.","Üzgünüz, seni kısaca kaybettik.");
add("de","A2","Deyimler","Ich schreibe dir lieber","sana yazmayı tercih ederim","Ausdruck","Ich schreibe dir lieber statt anzurufen.","Aramak yerine sana yazmayı tercih ederim.");
add("de","A2","Deyimler","Ruf mich einfach an","beni sadece ara","Ausdruck","Ruf mich einfach an, wenn du Zeit hast.","Vaktin olunca beni sadece ara.");
add("de","A2","Deyimler","Ich bin gerade beschäftigt","şu an meşgulüm","Ausdruck","Sorry, ich bin gerade wirklich beschäftigt.","Üzgünüm, şu an gerçekten meşgulüm.");
add("de","A2","Deyimler","Ich rufe dich später zurück","seni sonra geri ararım","Ausdruck","Sorry, ich rufe dich später zurück, versprochen.","Üzgünüm, seni sonra geri ararım, söz.");
add("de","A2","Deyimler","Kann ich später zurückrufen?","daha sonra geri arayabilir miyim?","Ausdruck","Kann ich dich später zurückrufen?","Seni daha sonra geri arayabilir miyim?");
add("de","A2","Deyimler","Ich habe deinen Anruf verpasst","aramanı kaçırdım","Ausdruck","Sorry, ich habe deinen Anruf leider verpasst.","Üzgünüm, maalesef aramanı kaçırdım.");
add("de","A2","Deyimler","Warum gehst du nicht ran?","neden telefonu açmıyorsun?","Ausdruck","Warum gehst du eigentlich nie ran?","Aslında neden hiç telefonu açmıyorsun?");
add("de","A2","Deyimler","Mein Handy war stumm","telefonum sessizdeydi","Ausdruck","Sorry, mein Handy war den ganzen Tag stumm.","Üzgünüm, telefonum tüm gün sessizdeydi.");
add("de","A2","Deyimler","Ich hatte kein Netz","şebeke çekmiyordu","Ausdruck","Sorry, ich hatte dort einfach kein Netz.","Üzgünüm, orada basitçe şebeke çekmiyordu.");
add("de","A2","Deyimler","Mein Akku war leer","pilim bitmişti","Ausdruck","Sorry, mein Akku war den ganzen Tag leer.","Üzgünüm, tüm gün pilim bitmişti.");
add("de","A2","Deyimler","Ich koche heute","bugün ben yemek yapıyorum","Ausdruck","Keine Sorge, ich koche heute Abend.","Merak etme, bu akşam ben yemek yapıyorum.");
add("de","A2","Deyimler","Was gibt es heute zu essen?","bugün yemekte ne var?","Ausdruck","Sag mal, was gibt es heute zu essen?","Söyle bakalım, bugün yemekte ne var?");
add("de","A2","Deyimler","Ich habe noch nichts gegessen","henüz bir şey yemedim","Ausdruck","Ehrlich, ich habe heute noch nichts gegessen.","Dürüst olmak gerekirse, bugün henüz bir şey yemedim.");
add("de","A2","Deyimler","Isst du schon zu Abend?","akşam yemeği yiyor musun?","Ausdruck","Sag mal, isst du schon zu Abend?","Söyle bakalım, akşam yemeği yiyor musun?");
add("de","A2","Deyimler","Lass uns zusammen essen gehen","hadi birlikte yemeğe gidelim","Ausdruck","Lass uns heute zusammen essen gehen.","Hadi bugün birlikte yemeğe gidelim.");
add("de","A2","Deyimler","Ich lade dich zum Essen ein","seni yemeğe davet ediyorum","Ausdruck","Komm, ich lade dich heute zum Essen ein.","Gel, bugün seni yemeğe davet ediyorum.");
add("de","A2","Deyimler","Greif zu","buyur, al (yemeğe)","Ausdruck","Greif einfach zu, iss so viel du willst.","Buyur al, istediğin kadar ye.");
add("de","A2","Deyimler","Lass es dir schmecken","afiyet olsun (yerken)","Ausdruck","Lass es dir gut schmecken!","Afiyet olsun!");
add("de","A2","Deyimler","Nimm dir noch etwas","biraz daha al","Ausdruck","Komm, nimm dir noch etwas Reis.","Hadi, biraz daha pirinç al.");
add("de","A2","Deyimler","Ich bin schon satt","zaten tokum","Ausdruck","Danke, aber ich bin schon wirklich satt.","Teşekkürler ama zaten gerçekten tokum.");
