add("de","A2","Deyimler","Du kochst wirklich gut","gerçekten iyi yemek yapıyorsun","Ausdruck","Ehrlich, du kochst wirklich richtig gut.","Dürüst olmak gerekirse, gerçekten çok iyi yemek yapıyorsun.");
add("de","A2","Deyimler","Kannst du mir das Rezept geben?","bana tarifi verebilir misin?","Ausdruck","Kannst du mir bitte das Rezept dafür geben?","Lütfen bunun tarifini bana verebilir misin?");
add("de","A2","Deyimler","Was ist die geheime Zutat?","gizli malzeme nedir?","Ausdruck","Sag mal, was ist die geheime Zutat?","Söyle bakalım, gizli malzeme nedir?");
add("de","A2","Deyimler","Es ist ein bisschen zu salzig","biraz fazla tuzlu","Ausdruck","Ehrlich, es ist mir ein bisschen zu salzig.","Dürüst olmak gerekirse, benim için biraz fazla tuzlu.");
add("de","A2","Deyimler","Es fehlt noch etwas Salz","biraz daha tuza ihtiyacı var","Ausdruck","Ehrlich, es fehlt noch etwas Salz.","Dürüst olmak gerekirse, biraz daha tuza ihtiyacı var.");
add("de","A2","Deyimler","Es ist perfekt gewürzt","tam kıvamında baharatlanmış","Ausdruck","Ehrlich, es ist perfekt gewürzt.","Dürüst olmak gerekirse, tam kıvamında baharatlanmış.");
add("de","A2","Deyimler","Ich bin allergisch dagegen","buna alerjim var","Ausdruck","Sorry, ich bin leider dagegen allergisch.","Üzgünüm, maalesef buna alerjim var.");
