add("de","A2","Deyimler","Ist da Fleisch drin?","içinde et var mı?","Ausdruck","Entschuldigung, ist da vielleicht Fleisch drin?","Affedersiniz, belki içinde et var mıdır?");
add("de","A2","Deyimler","Kann ich das ohne Zwiebeln haben?","bunu soğansız alabilir miyim?","Ausdruck","Kann ich das bitte ohne Zwiebeln haben?","Lütfen bunu soğansız alabilir miyim?");
add("de","A2","Deyimler","Ich esse alles außer Fisch","balık dışında her şeyi yerim","Ausdruck","Ehrlich, ich esse alles außer Fisch.","Dürüst olmak gerekirse, balık dışında her şeyi yerim.");
add("de","A2","Deyimler","Ich habe morgen frei","yarın izinliyim","Ausdruck","Zum Glück habe ich morgen frei.","İyi ki yarın izinliyim.");
add("de","A2","Deyimler","Ich muss heute arbeiten","bugün çalışmam gerekiyor","Ausdruck","Leider muss ich heute noch arbeiten.","Maalesef bugün hâlâ çalışmam gerekiyor.");
add("de","A2","Deyimler","Wie war die Arbeit heute?","iş bugün nasıldı?","Ausdruck","Na, wie war die Arbeit heute?","Peki, iş bugün nasıldı?");
add("de","A2","Deyimler","Die Arbeit war stressig","iş stresliydi","Ausdruck","Ehrlich, die Arbeit war heute richtig stressig.","Dürüst olmak gerekirse, bugün iş gerçekten stresliydi.");
add("de","A2","Deyimler","Ich brauche dringend Urlaub","acilen tatile ihtiyacım var","Ausdruck","Ehrlich, ich brauche jetzt dringend Urlaub.","Dürüst olmak gerekirse, şimdi acilen tatile ihtiyacım var.");
add("de","A2","Deyimler","Ich freue mich auf das Wochenende","hafta sonunu iple çekiyorum","Ausdruck","Ehrlich, ich freue mich schon so auf das Wochenende.","Dürüst olmak gerekirse, hafta sonunu şimdiden çok iple çekiyorum.");
add("de","A2","Deyimler","Endlich Feierabend","sonunda mesai bitti","Ausdruck","Endlich Feierabend, ich bin fertig!","Sonunda mesai bitti, bittim!");
add("de","A2","Deyimler","Ich mache jetzt Schluss","şimdi işi bırakıyorum","Ausdruck","Okay, ich mache jetzt wirklich Schluss.","Tamam, şimdi gerçekten işi bırakıyorum.");
add("de","A2","Deyimler","Ich bin für heute fertig","bugünlük bittim","Ausdruck","Endlich, ich bin für heute fertig.","Sonunda, bugünlük bittim.");
add("de","A2","Deyimler","Wir sehen uns morgen im Büro","yarın ofiste görüşürüz","Ausdruck","Okay, wir sehen uns dann morgen im Büro.","Tamam, o zaman yarın ofiste görüşürüz.");
add("de","A2","Deyimler","Schönen Feierabend noch","iyi akşamlar (mesai sonrası)","Ausdruck","Schönen Feierabend noch euch allen!","Hepinize iyi akşamlar!");
add("de","A2","Deyimler","Schönes Wochenende","iyi hafta sonları","Ausdruck","Schönes Wochenende und bis Montag!","İyi hafta sonları ve pazartesiye kadar!");
add("de","A2","Deyimler","Erhol dich gut am Wochenende","hafta sonu iyi dinlen","Ausdruck","Erhol dich gut am Wochenende, du hast es verdient.","Hafta sonu iyi dinlen, bunu hak ettin.");
add("de","A2","Deyimler","Ich muss früh raus","erken çıkmam gerekiyor","Ausdruck","Sorry, ich muss morgen früh raus.","Üzgünüm, yarın erken çıkmam gerekiyor.");
add("de","A2","Deyimler","Der Wecker klingelt zu früh","alarm çok erken çalıyor","Ausdruck","Ehrlich, der Wecker klingelt jeden Tag zu früh.","Dürüst olmak gerekirse, alarm her gün çok erken çalıyor.");
add("de","A2","Deyimler","Ich bin ein Morgenmensch","ben sabah insanıyım","Ausdruck","Ehrlich, ich bin einfach ein Morgenmensch.","Dürüst olmak gerekirse, ben basitçe sabah insanıyım.");
add("de","A2","Deyimler","Ich bin eher ein Nachtmensch","ben daha çok gece insanıyım","Ausdruck","Ehrlich, ich bin eher ein Nachtmensch.","Dürüst olmak gerekirse, ben daha çok gece insanıyım.");
add("de","A2","Deyimler","Ich bin nachts produktiver","geceleri daha üretkenim","Ausdruck","Ehrlich, ich bin nachts einfach produktiver.","Dürüst olmak gerekirse, geceleri basitçe daha üretkenim.");
add("de","A2","Deyimler","Ich schlafe gerne aus","uykumu almayı severim","Ausdruck","Am Wochenende schlafe ich gerne mal aus.","Hafta sonu uykumu almayı severim.");
add("de","A2","Deyimler","Ich brauche meinen Schönheitsschlaf","güzellik uykuma ihtiyacım var","Ausdruck","Ehrlich, ich brauche jetzt meinen Schönheitsschlaf.","Dürüst olmak gerekirse, şimdi güzellik uykuma ihtiyacım var.");
add("de","A2","Deyimler","Wie sieht dein Tagesablauf aus?","günün nasıl geçiyor (rutin)?","Ausdruck","Sag mal, wie sieht dein normaler Tagesablauf aus?","Söyle bakalım, normal günün nasıl geçiyor?");
add("de","A2","Deyimler","Ich stehe immer um sieben auf","her zaman yedide kalkarım","Ausdruck","Normalerweise stehe ich immer um sieben auf.","Normalde her zaman yedide kalkarım.");
add("de","A2","Deyimler","Zuerst dusche ich, dann frühstücke ich","önce duş alırım, sonra kahvaltı ederim","Ausdruck","Zuerst dusche ich, dann frühstücke ich schnell.","Önce duş alırım, sonra hızlıca kahvaltı ederim.");
add("de","A2","Deyimler","Danach gehe ich zur Arbeit","sonra işe giderim","Ausdruck","Danach gehe ich meistens direkt zur Arbeit.","Sonra genellikle doğrudan işe giderim.");
add("de","A2","Deyimler","Auf dem Weg zur Arbeit","işe giderken","Ausdruck","Auf dem Weg zur Arbeit höre ich Musik.","İşe giderken müzik dinlerim.");
add("de","A2","Deyimler","Nach der Arbeit gehe ich einkaufen","işten sonra alışverişe giderim","Ausdruck","Nach der Arbeit gehe ich oft noch einkaufen.","İşten sonra genellikle alışverişe de giderim.");
add("de","A2","Deyimler","Abends koche ich meistens selbst","akşamları genellikle kendim pişiririm","Ausdruck","Abends koche ich meistens selbst etwas Einfaches.","Akşamları genellikle kendim basit bir şeyler pişiririm.");
add("de","A2","Deyimler","Vor dem Schlafen lese ich noch","uyumadan önce biraz okurum","Ausdruck","Vor dem Schlafen lese ich noch ein bisschen.","Uyumadan önce biraz okurum.");
add("de","A2","Deyimler","Das ist meine tägliche Routine","bu benim günlük rutinim","Ausdruck","Das ist einfach meine tägliche Routine.","Bu basitçe benim günlük rutinim.");
add("de","A2","Deyimler","Ich versuche, gesund zu leben","sağlıklı yaşamaya çalışıyorum","Ausdruck","Ehrlich, ich versuche wirklich, gesund zu leben.","Dürüst olmak gerekirse, gerçekten sağlıklı yaşamaya çalışıyorum.");
add("de","A2","Deyimler","Ich versuche, mehr Sport zu machen","daha fazla spor yapmaya çalışıyorum","Ausdruck","Ehrlich, ich versuche, dieses Jahr mehr Sport zu machen.","Dürüst olmak gerekirse, bu yıl daha fazla spor yapmaya çalışıyorum.");
add("de","A2","Deyimler","Ich habe mir vorgenommen, weniger Zucker zu essen","daha az şeker yemeye karar verdim","Ausdruck","Ich habe mir vorgenommen, weniger Zucker zu essen.","Daha az şeker yemeye karar verdim.");
add("de","A2","Deyimler","Das ist mein guter Vorsatz","bu benim iyi niyetim (kararım)","Ausdruck","Ehrlich, das ist einfach mein guter Vorsatz für dieses Jahr.","Dürüst olmak gerekirse, bu basitçe bu yılki iyi niyetim.");
add("de","A2","Deyimler","Ich halte mich meistens daran","genellikle buna bağlı kalırım","Ausdruck","Ehrlich, ich halte mich meistens ziemlich gut daran.","Dürüst olmak gerekirse, genellikle buna oldukça iyi bağlı kalırım.");
add("de","A2","Deyimler","Manchmal fällt es mir schwer","bazen bu benim için zor oluyor","Ausdruck","Ehrlich, manchmal fällt es mir wirklich schwer.","Dürüst olmak gerekirse, bazen bu benim için gerçekten zor oluyor.");
add("de","A2","Deyimler","Was steht auf dem Programm?","programda ne var?","Ausdruck","Sag mal, was steht heute auf dem Programm?","Söyle bakalım, bugün programda ne var?");
add("de","A2","Deyimler","Was steht als Nächstes an?","sırada ne var?","Ausdruck","Sag mal, was steht als Nächstes an?","Söyle bakalım, sırada ne var?");
add("de","A2","Deyimler","Wir haben noch viel vor","hâlâ çok planımız var","Ausdruck","Ehrlich, wir haben heute noch viel vor.","Dürüst olmak gerekirse, bugün hâlâ çok planımız var.");
add("de","A2","Deyimler","Lass uns den Tag planen","hadi günü planlayalım","Ausdruck","Okay, lass uns kurz den Tag planen.","Tamam, hadi kısaca günü planlayalım.");
add("de","A2","Deyimler","Womit fangen wir an?","neyle başlıyoruz?","Ausdruck","Okay, womit fangen wir zuerst an?","Tamam, önce neyle başlıyoruz?");
add("de","A2","Deyimler","Fangen wir mit dem Wichtigsten an","en önemli şeyle başlayalım","Ausdruck","Okay, fangen wir einfach mit dem Wichtigsten an.","Tamam, hadi sadece en önemli şeyle başlayalım.");
add("de","A2","Deyimler","Das kommt später dran","bu daha sonra sırada","Ausdruck","Keine Sorge, das kommt später noch dran.","Merak etme, bu daha sonra sırada.");
add("de","A2","Deyimler","Das können wir auf später verschieben","bunu sonraya erteleyebiliriz","Ausdruck","Okay, das können wir gut auf später verschieben.","Tamam, bunu iyi bir şekilde sonraya erteleyebiliriz.");
add("de","A2","Deyimler","Wir haben genug für heute gemacht","bugünlük yeterince yaptık","Ausdruck","Okay, ich glaube, wir haben genug für heute gemacht.","Tamam, sanırım bugünlük yeterince yaptık.");
add("de","A2","Deyimler","Machen wir morgen weiter","yarın devam edelim","Ausdruck","Okay, machen wir einfach morgen weiter.","Tamam, hadi sadece yarın devam edelim.");
add("de","A2","Deyimler","Wir haben den ganzen Tag vor uns","önümüzde koca bir gün var","Ausdruck","Super, wir haben den ganzen Tag noch vor uns.","Harika, önümüzde hâlâ koca bir gün var.");
add("de","A2","Deyimler","Der Tag ist noch jung","gün henüz genç","Ausdruck","Keine Sorge, der Tag ist ja noch jung.","Merak etme, gün henüz genç.");
add("de","A2","Deyimler","Es ist noch reichlich Zeit","hâlâ bolca zaman var","Ausdruck","Entspann dich, es ist noch reichlich Zeit.","Rahatla, hâlâ bolca zaman var.");
add("de","A2","Deyimler","Ich bin noch neu hier","burada henüz yeniyim","Ausdruck","Entschuldigung, ich bin noch neu hier.","Affedersiniz, burada henüz yeniyim.");
add("de","A2","Deyimler","Ich kenne mich hier noch nicht aus","burayı henüz tanımıyorum","Ausdruck","Ehrlich, ich kenne mich hier noch nicht so aus.","Dürüst olmak gerekirse, burayı henüz pek tanımıyorum.");
add("de","A2","Deyimler","Können Sie mir die Stadt zeigen?","bana şehri gösterebilir misiniz?","Ausdruck","Könnten Sie mir vielleicht die Stadt zeigen?","Belki bana şehri gösterebilir misiniz?");
add("de","A2","Deyimler","Was empfehlen Sie mir?","bana ne önerirsiniz?","Ausdruck","Entschuldigung, was empfehlen Sie mir hier?","Affedersiniz, burada bana ne önerirsiniz?");
add("de","A2","Deyimler","Was ist hier sehenswert?","burada görülmeye değer ne var?","Ausdruck","Entschuldigung, was ist hier in der Stadt sehenswert?","Affedersiniz, şehirde burada görülmeye değer ne var?");
add("de","A2","Deyimler","Ich möchte die Gegend erkunden","bölgeyi keşfetmek istiyorum","Ausdruck","Ich möchte gerne die Gegend etwas erkunden.","Bölgeyi biraz keşfetmek istiyorum.");
add("de","A2","Deyimler","Es ist einen Besuch wert","ziyaret etmeye değer","Ausdruck","Ehrlich, dieser Ort ist wirklich einen Besuch wert.","Dürüst olmak gerekirse, bu yer gerçekten ziyaret etmeye değer.");
add("de","A2","Deyimler","Das darfst du nicht verpassen","bunu kaçırmamalısın","Ausdruck","Ehrlich, das darfst du wirklich nicht verpassen.","Dürüst olmak gerekirse, bunu gerçekten kaçırmamalısın.");
add("de","A2","Deyimler","Es lohnt sich, dorthin zu gehen","oraya gitmeye değer","Ausdruck","Ehrlich, es lohnt sich wirklich, dorthin zu gehen.","Dürüst olmak gerekirse, oraya gitmeye gerçekten değer.");
add("de","A2","Deyimler","Wie ist die Stimmung dort?","oranın atmosferi nasıl?","Ausdruck","Sag mal, wie ist die Stimmung dort abends?","Söyle bakalım, orada akşamları atmosfer nasıl?");
add("de","A2","Deyimler","Es hat mir dort sehr gefallen","orayı çok beğendim","Ausdruck","Ehrlich, es hat mir dort wirklich sehr gefallen.","Dürüst olmak gerekirse, orayı gerçekten çok beğendim.");
add("de","A2","Deyimler","Ich möchte gerne wiederkommen","tekrar gelmek istiyorum","Ausdruck","Ehrlich, ich möchte hierher gerne wiederkommen.","Dürüst olmak gerekirse, buraya tekrar gelmek istiyorum.");
add("de","A2","Deyimler","Ich habe hier tolle Erinnerungen","burada harika anılarım var","Ausdruck","Ehrlich, ich habe hier wirklich tolle Erinnerungen.","Dürüst olmak gerekirse, burada gerçekten harika anılarım var.");
add("de","A2","Deyimler","Was für ein Zufall","ne tesadüf","Ausdruck","Was für ein Zufall, dich hier zu treffen!","Seni burada görmek ne tesadüf!");
add("de","A2","Deyimler","Die Welt ist klein","dünya küçük","Ausdruck","Wow, die Welt ist wirklich klein!","Vay, dünya gerçekten çok küçük!");
add("de","A2","Deyimler","Das ist ja ein Ding","işte bu bir şey (şaşırma)","Ausdruck","Na so was, das ist ja ein Ding!","Vay canına, işte bu bir şey!");
add("de","A2","Deyimler","Sowas Verrücktes","ne çılgınca bir şey","Ausdruck","Sowas Verrücktes habe ich noch nie erlebt.","Böyle çılgınca bir şeyi hiç yaşamamıştım.");
add("de","A2","Deyimler","Das gibt's doch nicht","olamaz böyle bir şey","Ausdruck","Das gibt's doch gar nicht!","Böyle bir şey olamaz!");
add("de","A2","Deyimler","Ich trau meinen Augen nicht","gözlerime inanamıyorum","Ausdruck","Ehrlich, ich trau meinen Augen einfach nicht.","Dürüst olmak gerekirse, gözlerime basitçe inanamıyorum.");
add("de","A2","Deyimler","Meine Güte","aman Tanrım","Ausdruck","Meine Güte, ist das groß!","Aman Tanrım, bu ne kadar büyük!");
add("de","A2","Deyimler","Ach du meine Güte","aman Tanrım","Ausdruck","Ach du meine Güte, was ist passiert?","Aman Tanrım, ne oldu?");
add("de","A2","Deyimler","Um Gottes willen","Allah aşkına","Ausdruck","Um Gottes willen, pass doch auf!","Allah aşkına, dikkat et!");
add("de","A2","Deyimler","Junge, Junge","vay be (şaşkınlık)","Ausdruck","Junge, Junge, das war knapp!","Vay be, bu ucu ucuna oldu!");
add("de","A2","Deyimler","Na sowas","bak sen şuna","Ausdruck","Na sowas, das hätte ich nicht gedacht.","Bak sen şuna, bunu düşünmezdim.");
add("de","A2","Deyimler","Ach herrje","aman aman","Ausdruck","Ach herrje, jetzt ist es kaputt.","Aman aman, şimdi bozuldu.");
add("de","A2","Deyimler","Ich bin noch am Überlegen","hâlâ düşünüyorum","Ausdruck","Ehrlich, ich bin noch am Überlegen, was ich tun soll.","Dürüst olmak gerekirse, ne yapacağımı hâlâ düşünüyorum.");
add("de","A2","Deyimler","Ich bin am Kochen","yemek pişiriyorum (şu an)","Ausdruck","Sorry, ich bin gerade am Kochen.","Üzgünüm, şu an yemek pişiriyorum.");
add("de","A2","Deyimler","Ich bin gerade am Arbeiten","şu an çalışıyorum","Ausdruck","Sorry, ich bin gerade am Arbeiten.","Üzgünüm, şu an çalışıyorum.");
add("de","A2","Deyimler","Ich bin dabei, es fertigzumachen","onu bitirmek üzereyim","Ausdruck","Warte, ich bin gerade dabei, es fertigzumachen.","Bekle, onu bitirmek üzereyim.");
add("de","A2","Deyimler","Ich bin am Überlegen, ob ich mitkomme","gelip gelmeyeceğimi düşünüyorum","Ausdruck","Ehrlich, ich bin noch am Überlegen, ob ich mitkomme.","Dürüst olmak gerekirse, gelip gelmeyeceğimi hâlâ düşünüyorum.");
add("de","A2","Deyimler","Ich bin kurz davor, aufzugeben","pes etmek üzereyim","Ausdruck","Ehrlich, ich bin kurz davor, einfach aufzugeben.","Dürüst olmak gerekirse, basitçe pes etmek üzereyim.");
add("de","A2","Deyimler","Ich stehe kurz vor dem Abschluss","bitirmek üzereyim","Ausdruck","Ehrlich, ich stehe kurz vor dem Abschluss meines Projekts.","Dürüst olmak gerekirse, projemi bitirmek üzereyim.");
add("de","A2","Deyimler","Es ist fast geschafft","neredeyse bitti","Ausdruck","Halt durch, es ist fast geschafft.","Dayan, neredeyse bitti.");
add("de","A2","Deyimler","Wir sind fast am Ziel","hedefe neredeyse ulaştık","Ausdruck","Kommt, wir sind fast am Ziel!","Gelin, hedefe neredeyse ulaştık!");
add("de","A2","Deyimler","Nur noch ein bisschen","sadece biraz daha","Ausdruck","Halt durch, nur noch ein bisschen.","Dayan, sadece biraz daha.");
add("de","A2","Deyimler","Gleich haben wir es","az kaldı bitecek","Ausdruck","Kommt, gleich haben wir es geschafft!","Gelin, az kaldı başaracağız!");
add("de","A2","Deyimler","Ich hab mich vertan","yanıldım","Ausdruck","Sorry, ich hab mich wohl vertan.","Üzgünüm, herhalde yanıldım.");
add("de","A2","Deyimler","Da hast du recht gehabt","o konuda haklıymışsın","Ausdruck","Ehrlich, da hast du wohl recht gehabt.","Dürüst olmak gerekirse, o konuda herhalde haklıymışsın.");
add("de","A2","Deyimler","Ich hab mich geirrt","hata yapmışım","Ausdruck","Sorry, ich hab mich da wohl geirrt.","Üzgünüm, o konuda herhalde hata yapmışım.");
add("de","A2","Deyimler","Ich gebe zu, dass ich falsch lag","yanıldığımı kabul ediyorum","Ausdruck","Ehrlich, ich gebe zu, dass ich falsch lag.","Dürüst olmak gerekirse, yanıldığımı kabul ediyorum.");
add("de","A2","Deyimler","Ich muss dir recht geben","sana hak vermem gerekiyor","Ausdruck","Ehrlich, ich muss dir da recht geben.","Dürüst olmak gerekirse, o konuda sana hak vermem gerekiyor.");
add("de","A2","Deyimler","Zugegeben, das war nicht klug","itiraf edeyim, bu akıllıca değildi","Ausdruck","Zugegeben, das war von mir nicht klug.","İtiraf edeyim, bu benden akıllıca değildi.");
add("de","A2","Deyimler","Rückblickend betrachtet","geriye dönüp bakınca","Ausdruck","Rückblickend betrachtet, war das ein Fehler.","Geriye dönüp bakınca, bu bir hataydı.");
add("de","A2","Deyimler","Im Nachhinein","sonradan düşününce","Ausdruck","Im Nachhinein hätte ich anders gehandelt.","Sonradan düşününce, farklı davranırdım.");
add("de","A2","Deyimler","Hätte ich das nur gewusst","keşke bunu bilseydim","Ausdruck","Hätte ich das nur früher gewusst!","Keşke bunu daha önce bilseydim!");
add("de","A2","Deyimler","Wenn ich das gewusst hätte","eğer bunu bilseydim","Ausdruck","Wenn ich das gewusst hätte, wäre ich nicht gekommen.","Eğer bunu bilseydim, gelmezdim.");
add("de","A2","Deyimler","Das ist eine andere Geschichte","bu başka bir hikaye","Ausdruck","Das ist aber eine ganz andere Geschichte.","Ama bu tamamen başka bir hikaye.");
add("de","A2","Deyimler","Das ist eine lange Geschichte","bu uzun bir hikaye","Ausdruck","Ach, das ist eine ziemlich lange Geschichte.","Ah, bu oldukça uzun bir hikaye.");
add("de","A2","Deyimler","Lange Geschichte kurz","uzun lafın kısası","Ausdruck","Lange Geschichte kurz, es hat geklappt.","Uzun lafın kısası, işe yaradı.");
add("de","A2","Deyimler","Um es kurz zu machen","kısaca söylemek gerekirse","Ausdruck","Um es kurz zu machen, wir haben verloren.","Kısaca söylemek gerekirse, kaybettik.");
add("de","A2","Deyimler","Ich mach's kurz","kısa keseceğim","Ausdruck","Okay, ich mach's jetzt kurz.","Tamam, şimdi kısa keseceğim.");
add("de","A2","Deyimler","Lang und breit erzählen","uzun uzadıya anlatmak","Ausdruck","Er erzählt das immer lang und breit.","Bunu her zaman uzun uzadıya anlatıyor.");
add("de","A2","Deyimler","Ohne Umschweife","lafı dolandırmadan","Ausdruck","Ohne Umschweife, wir müssen reden.","Lafı dolandırmadan, konuşmamız gerekiyor.");
add("de","A2","Deyimler","Direkt zur Sache kommen","doğrudan konuya girmek","Ausdruck","Lass uns direkt zur Sache kommen.","Hadi doğrudan konuya girelim.");
add("de","A2","Deyimler","Ohne weitere Umschweife","daha fazla lafı uzatmadan","Ausdruck","Ohne weitere Umschweife, hier ist der Plan.","Lafı daha fazla uzatmadan, işte plan.");
add("de","A2","Deyimler","Ich bin ganz deiner Meinung","tamamen senin fikrindeyim","Ausdruck","Ehrlich, ich bin da ganz deiner Meinung.","Dürüst olmak gerekirse, o konuda tamamen senin fikrindeyim.");
add("de","A2","Deyimler","Da bin ich mir nicht so sicher","o konuda pek emin değilim","Ausdruck","Ehrlich, da bin ich mir nicht so sicher.","Dürüst olmak gerekirse, o konuda pek emin değilim.");
add("de","A2","Deyimler","Das würde ich nicht sagen","bunu söylemezdim","Ausdruck","Ehrlich, das würde ich so nicht sagen.","Dürüst olmak gerekirse, bunu böyle söylemezdim.");
add("de","A2","Deyimler","Das kann man so nicht sagen","bunu böyle söylemek doğru olmaz","Ausdruck","Ehrlich, das kann man so einfach nicht sagen.","Dürüst olmak gerekirse, bunu böyle basitçe söylemek doğru olmaz.");
add("de","A2","Deyimler","Es kommt darauf an, wie man es sieht","nasıl baktığına bağlı","Ausdruck","Ehrlich, es kommt darauf an, wie man es sieht.","Dürüst olmak gerekirse, nasıl baktığına bağlı.");
add("de","A2","Deyimler","Aus einer anderen Perspektive","farklı bir bakış açısından","Ausdruck","Aus einer anderen Perspektive gesehen, ist das positiv.","Farklı bir bakış açısından bakıldığında, bu olumlu.");
add("de","A2","Deyimler","Auf der anderen Seite","öte yandan","Ausdruck","Auf der anderen Seite hat er auch recht.","Öte yandan o da haklı.");
add("de","A2","Deyimler","Andererseits","diğer taraftan","Ausdruck","Andererseits ist das auch ein guter Punkt.","Diğer taraftan bu da iyi bir nokta.");
add("de","A2","Deyimler","Wo waren wir stehen geblieben?","kaldığımız yer neresiydi?","Ausdruck","Okay, wo waren wir gerade stehen geblieben?","Tamam, tam kaldığımız yer neresiydi?");
add("de","A2","Deyimler","Machen wir da weiter, wo wir aufgehört haben","kaldığımız yerden devam edelim","Ausdruck","Okay, machen wir einfach da weiter, wo wir aufgehört haben.","Tamam, hadi sadece kaldığımız yerden devam edelim.");
add("de","A2","Deyimler","Ich habe den Faden verloren","konuyu kaybettim (dikkatimi)","Ausdruck","Sorry, ich habe gerade den Faden verloren.","Üzgünüm, şu an konuyu kaybettim.");
add("de","A2","Deyimler","Wo war ich stehen geblieben?","nerede kalmıştım?","Ausdruck","Moment, wo war ich gerade stehen geblieben?","Bir dakika, tam nerede kalmıştım?");
add("de","A2","Deyimler","Ach ja, genau","ah evet, doğru","Ausdruck","Ach ja, genau, das wollte ich sagen.","Ah evet, doğru, bunu söylemek istemiştim.");
add("de","A2","Deyimler","Wo waren wir gerade?","tam neredeydik?","Ausdruck","Okay, wo waren wir gerade in der Geschichte?","Tamam, hikayede tam neredeydik?");
add("de","A2","Deyimler","Sag mal ehrlich","dürüstçe söyle","Ausdruck","Sag mal ehrlich, was denkst du wirklich?","Dürüstçe söyle, gerçekten ne düşünüyorsun?");
add("de","A2","Deyimler","Ganz unter uns gesagt","aramızda kalsın diye söylüyorum","Ausdruck","Ganz unter uns gesagt, ich mag ihn nicht.","Aramızda kalsın diye söylüyorum, onu sevmiyorum.");
add("de","A2","Deyimler","Wenn ich ehrlich sein soll","dürüst olmam gerekirse","Ausdruck","Wenn ich ehrlich sein soll, war es nicht gut.","Dürüst olmam gerekirse, iyi değildi.");
add("de","A2","Deyimler","Streng genommen","tam anlamıyla / sıkı bir şekilde","Ausdruck","Streng genommen hat er nicht ganz unrecht.","Tam anlamıyla, o tamamen haksız değil.");
add("de","A2","Deyimler","Genau genommen","tam olarak / hassasiyetle","Ausdruck","Genau genommen war es ein Montag.","Tam olarak, pazartesiydi.");
add("de","A2","Deyimler","Es sei denn, es passiert etwas","bir şey olmadıkça","Ausdruck","Ich komme, es sei denn, es passiert etwas.","Bir şey olmadıkça geleceğim.");
add("de","A2","Deyimler","Vorausgesetzt, alles läuft gut","her şey yolunda giderse","Ausdruck","Vorausgesetzt, alles läuft gut, sind wir pünktlich.","Her şey yolunda giderse, zamanında oluruz.");
add("de","A2","Deyimler","Es gibt nichts mehr zu sagen","söylenecek başka bir şey yok","Ausdruck","Ehrlich, es gibt jetzt nichts mehr zu sagen.","Dürüst olmak gerekirse, artık söylenecek başka bir şey yok.");
add("de","A2","Deyimler","Damit ist alles gesagt","böylece her şey söylendi","Ausdruck","Gut, damit ist eigentlich alles gesagt.","İyi, böylece aslında her şey söylendi.");
add("de","A2","Deyimler","Ich habe nichts mehr hinzuzufügen","eklemek istediğim bir şey yok","Ausdruck","Ehrlich, ich habe dazu nichts mehr hinzuzufügen.","Dürüst olmak gerekirse, buna eklemek istediğim bir şey yok.");
add("de","A2","Deyimler","Das war's von meiner Seite aus","benim tarafımdan söylenecekler bu kadardı","Ausdruck","Okay, das war's dann von meiner Seite aus.","Tamam, o zaman benim tarafımdan söylenecekler bu kadardı.");
add("de","A2","Deyimler","Ich glaube, wir sind fertig hier","sanırım burada işimiz bitti","Ausdruck","Okay, ich glaube, wir sind hier fertig.","Tamam, sanırım burada işimiz bitti.");
add("de","A2","Deyimler","Damit schließe ich","böylece kapatıyorum (konuşmayı)","Ausdruck","Damit schließe ich meine kurze Rede.","Böylece kısa konuşmamı kapatıyorum.");
add("de","A2","Deyimler","Wir werden sehen","göreceğiz","Ausdruck","Okay, wir werden ja sehen.","Tamam, göreceğiz.");
add("de","A2","Deyimler","Man wird sehen","zaman gösterecek","Ausdruck","Man wird sehen, wie es ausgeht.","Nasıl sonuçlanacağını zaman gösterecek.");
add("de","A2","Deyimler","Die Zukunft wird es zeigen","gelecek gösterecek","Ausdruck","Die Zukunft wird es uns zeigen.","Gelecek bize gösterecek.");
add("de","A2","Deyimler","Warten wir es ab","bekleyip görelim","Ausdruck","Warten wir es einfach ab.","Sadece bekleyip görelim.");
